package oviewer

import (
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"strings"
	"time"

	"github.com/BurntSushi/toml"
	"gopkg.in/yaml.v3"
)

// Converter names.
const (
	ConvEscaped = "es"
	ConvRaw     = "raw"
	ConvAlign   = "align"
)

// OVStyle represents a style configuration entry.
type OVStyle struct {
	Background     string `yaml:"Background"`
	Foreground     string `yaml:"Foreground"`
	UnderlineColor string `yaml:"UnderlineColor"`
	UnderlineStyle string `yaml:"UnderlineStyle"`
	Bold           *bool  `yaml:"Bold"`
	Blink          *bool  `yaml:"Blink"`
