	UnBold          *bool `yaml:"UnBold"`
	UnBlink         *bool `yaml:"UnBlink"`
	UnDim           *bool `yaml:"UnDim"`
	UnItalic        *bool `yaml:"UnItalic"`
	UnUnderline     *bool `yaml:"UnUnderline"`
	UnStrikeThrough *bool `yaml:"UnStrikeThrough"`
	UnReverse       *bool `yaml:"UnReverse"`
}

// StyleConfig holds all configurable styles.
type StyleConfig struct {
	ColumnRainbow        []OVStyle `yaml:"ColumnRainbow"`
	MultiColorHighlight  []OVStyle `yaml:"MultiColorHighlight"`
	Header               *OVStyle  `yaml:"Header"`
	Body                 *OVStyle  `yaml:"Body"`
	LineNumber           *OVStyle  `yaml:"LineNumber"`
	SearchHighlight      *OVStyle  `yaml:"SearchHighlight"`
	ColumnHighlight      *OVStyle  `yaml:"ColumnHighlight"`
	MarkLine             *OVStyle  `yaml:"MarkLine"`
	SectionLine          *OVStyle  `yaml:"SectionLine"`
	VerticalHeader       *OVStyle  `yaml:"VerticalHeader"`
	JumpTargetLine       *OVStyle  `yaml:"JumpTargetLine"`
	Alternate            *OVStyle  `yaml:"Alternate"`
	Ruler                *OVStyle  `yaml:"Ruler"`
	HeaderBorder         *OVStyle  `yaml:"HeaderBorder"`
	SectionHeaderBorder  *OVStyle  `yaml:"SectionHeaderBorder"`
	VerticalHeaderBorder *OVStyle  `yaml:"VerticalHeaderBorder"`
	OverStrike           *OVStyle  `yaml:"OverStrike"`
	OverLine             *OVStyle  `yaml:"OverLine"`
}

// PromptConfig holds prompt configuration.
type PromptConfig struct {
	Normal struct {
		ShowFilename   *bool `yaml:"ShowFilename"`
		InvertColor    *bool `yaml:"InvertColor"`
		ProcessOfCount *bool `yaml:"ProcessOfCount"`
		CursorType     *int  `yaml:"CursorType"`
	} `yaml:"Normal"`
	Input struct {
		CursorType *int `yaml:"CursorType"`
	} `yaml:"Input"`
}

// RunTimeSettings holds the settings that may be overridden by a view mode.
// Pointer fields distinguish "not set" from "set to zero".
type RunTimeSettings struct {
	TabWidth             *int     `yaml:"TabWidth"`
	Header               *int     `yaml:"Header"`
	SkipLines            *int     `yaml:"SkipLines"`
	VerticalHeader       *int     `yaml:"VerticalHeader"`
	HeaderColumn         *int     `yaml:"HeaderColumn"`
	WatchInterval        *int     `yaml:"WatchInterval"`
	MarkStyleWidth       *int     `yaml:"MarkStyleWidth"`
	SectionStartPosition *int     `yaml:"SectionStartPosition"`
	SectionHeaderNum     *int     `yaml:"SectionHeaderNum"`
	RulerType            *int     `yaml:"RulerType"`
	VScrollLines         *int     `yaml:"VScrollLines"`
	HScrollWidth         string   `yaml:"HScrollWidth"`
	JumpTarget           string   `yaml:"JumpTarget"`
	ColumnDelimiter      *string  `yaml:"ColumnDelimiter"`
	SectionDelimiter     *string  `yaml:"SectionDelimiter"`
	Caption              string   `yaml:"Caption"`
	Converter            string   `yaml:"Converter"`
	MultiColorWords      []string `yaml:"MultiColorWords"`
	AlternateRows        *bool    `yaml:"AlternateRows"`
	ColumnMode           *bool    `yaml:"ColumnMode"`
	ColumnWidth          *bool    `yaml:"ColumnWidth"`
	ColumnRainbow        *bool    `yaml:"ColumnRainbow"`
	LineNumMode          *bool    `yaml:"LineNumMode"`
	WrapMode             *bool    `yaml:"WrapMode"`
	FollowMode           *bool    `yaml:"FollowMode"`
	FollowAll            *bool    `yaml:"FollowAll"`
	FollowSection        *bool    `yaml:"FollowSection"`
	FollowName           *bool    `yaml:"FollowName"`
	PlainMode            *bool    `yaml:"PlainMode"`
	SectionHeader        *bool    `yaml:"SectionHeader"`
	HideOtherSection     *bool    `yaml:"HideOtherSection"`
	StatusLine           *bool    `yaml:"StatusLine"`
	Prompt               PromptConfig `yaml:"Prompt"`
	Style                StyleConfig  `yaml:"Style"`
}

// Config is the top level configuration.
type Config struct {
	General             RunTimeSettings            `yaml:"General"`
	Mode                map[string]RunTimeSettings `yaml:"Mode"`
	StyleOverStrike     *OVStyle                   `yaml:"StyleOverStrike"`
	StyleOverLine       *OVStyle                   `yaml:"StyleOverLine"`
	Keybind             map[string][]string        `yaml:"KeyBind"`
	DefaultKeyBind      string                     `yaml:"DefaultKeyBind"`
	ViewMode            string                     `yaml:"ViewMode"`
	ClipboardMethod     string                     `yaml:"ClipboardMethod"`
	ShrinkChar          string                     `yaml:"ShrinkChar"`
	ReadWaitTime        string                     `yaml:"ReadWaitTime"`
	MemoryLimit         int                        `yaml:"MemoryLimit"`
	MemoryLimitFile     int                        `yaml:"MemoryLimitFile"`
	BeforeWriteOriginal int                        `yaml:"BeforeWriteOriginal"`
	AfterWriteOriginal  int                        `yaml:"AfterWriteOriginal"`
	NotifyEOF           int                        `yaml:"NotifyEOF"`
	QuitSmall           bool                       `yaml:"QuitSmall"`
	IsWriteOriginal     bool                       `yaml:"IsWriteOriginal"`
	CaseSensitive       bool                       `yaml:"CaseSensitive"`
	SmartCaseSensitive  bool                       `yaml:"SmartCaseSensitive"`
	RegexpSearch        bool                       `yaml:"RegexpSearch"`
	Incsearch           bool                       `yaml:"Incsearch"`
	DisableMouse        bool                       `yaml:"DisableMouse"`
	DisableColumnCycle  bool                       `yaml:"DisableColumnCycle"`
	DisableStickyFollow bool                       `yaml:"DisableStickyFollow"`
	SetTerminalTitle    bool                       `yaml:"SetTerminalTitle"`
	Debug               bool                       `yaml:"Debug"`
	SkipExtract         bool                       `yaml:"SkipExtract"`
}

// NewConfig returns a Config with default values.
func NewConfig() Config {
	return Config{
		MemoryLimit:     -1,
		MemoryLimitFile: 100,
		Incsearch:       true,
		Mode:            map[string]RunTimeSettings{},
		Keybind:         map[string][]string{},
	}
}

var (
	configFileUsed string
	debugMode      bool
)

// SetConfigFile records the config file path.
func SetConfigFile(path string) { configFileUsed = path }

// SetDebug sets debug mode.
func SetDebug(b bool) { debugMode = b }

// ReadWaitDuration returns the parsed ReadWaitTime or the default (1s).
func (c Config) ReadWaitDuration() time.Duration {
	if c.ReadWaitTime == "" {
		return time.Second
	}
	d, err := time.ParseDuration(c.ReadWaitTime)
	if err != nil {
		return time.Second
	}
	return d
}

// LoadConfig reads the configuration file.
// If cfgFile is empty, the default locations are searched.
// Errors are reported in the same manner as the original tool
// ("failed to read config file: ...") but never fatal.
func LoadConfig(cfgFile string) (Config, error) {
	cfg := NewConfig()
	path := cfgFile
	if path == "" {
		path = findDefaultConfig()
		if path == "" {
			return cfg, nil
		}
	}
	data, err := os.ReadFile(path)
	if err != nil {
		if cfgFile == "" {
			return cfg, nil
		}
		return cfg, fmt.Errorf("failed to read config file: %w", err)
	}
	if err := decodeConfig(path, data, &cfg); err != nil {
		return cfg, fmt.Errorf("failed to read config file: %w", err)
	}
	if cfg.Mode == nil {
		cfg.Mode = map[string]RunTimeSettings{}
	}
	if cfg.Keybind == nil {
		cfg.Keybind = map[string][]string{}
	}
	if debugMode || cfg.Debug {
		fmt.Fprintf(os.Stderr, "Using config file: %s\n", path)
	}
	return cfg, nil
}

func decodeConfig(path string, data []byte, cfg *Config) error {
	ext := strings.TrimPrefix(strings.ToLower(filepath.Ext(path)), ".")
	switch ext {
	case "yaml", "yml", "json":
		// JSON is a subset of YAML.
		if err := yaml.Unmarshal(data, cfg); err != nil {
			return fmt.Errorf("While parsing config: %w", err)
		}
	case "toml":
		if err := toml.Unmarshal(data, cfg); err != nil {
			return fmt.Errorf("While parsing config: %w", err)
		}
	default:
		return fmt.Errorf("Unsupported Config Type %q", ext)
	}
	return nil
}

// findDefaultConfig searches for the config in the default locations:
// $XDG_CONFIG_HOME/ov/config.yaml (or $HOME/.config/ov/config.yaml) and $HOME/.ov.yaml.
func findDefaultConfig() string {
	exts := []string{"yaml", "yml", "json", "toml"}
	xdg := os.Getenv("XDG_CONFIG_HOME")
	home, herr := os.UserHomeDir()
	if xdg == "" && herr == nil {
		xdg = filepath.Join(home, ".config")
	}
	if xdg != "" {
		for _, e := range exts {
			p := filepath.Join(xdg, "ov", "config."+e)
			if fileExists(p) {
				return p
			}
		}
	}
	if herr == nil {
		for _, e := range exts {
			p := filepath.Join(home, ".ov."+e)
			if fileExists(p) {
				return p
			}
		}
	}
	return ""
}

func fileExists(p string) bool {
	st, err := os.Stat(p)
	return err == nil && !st.IsDir()
}

// ListViewModes prints the available view modes.
func ListViewModes(cfg Config) {
	fmt.Println("general")
	names := make([]string, 0, len(cfg.Mode))
	for k := range cfg.Mode {
		names = append(names, k)
	}
	sortStrings(names)
	for _, n := range names {
		fmt.Println(n)
	}
}

// ErrInvalidMode is returned for an unknown view mode.
var ErrInvalidMode = errors.New("invalid view mode")
EOF
echo ok"}

