package oviewer

import (
	"strconv"
	"strings"
	"unicode/utf8"

	"github.com/gdamore/tcell/v2"
	"github.com/mattn/go-runewidth"
)

// content represents one screen cell.
type content struct {
	style tcell.Style
	combc []rune
	width int
	mainc rune
}

// contents is a slice of cells (one logical line).
type contents []content

// Special cell markers.
const (
	// cellPlaceholder is the second cell of a wide character.
	cellPlaceholder = rune(0)
)

// SpaceContent is a blank cell.
var SpaceContent = content{mainc: ' ', width: 1, style: tcell.StyleDefault}

// DefaultContent is a cell used for padding.
var DefaultContent = content{mainc: 0, width: 0, style: tcell.StyleDefault}

// parseState keeps the state of the escape sequence parser across a line.
type parseState struct {
	style     tcell.Style
	tabWidth  int
	plain     bool
	overStrike tcell.Style
	overLine   tcell.Style
	// bsFlag is set after a backspace was seen.
	bsFlag  bool
