// isControl reports whether r is a control character that is displayed as a space.
func isControl(r rune) bool {
	return (r < 0x20 && r != '\t' && r != '\x1b' && r != '\b' && r != '\r') || r == 0x7f
}

// StrToContents converts a raw line into cells using tab width, expanding
// escape sequences and handling overstrikes.
func StrToContents(str string, tabWidth int) contents {
	return parseString(newParseState(tabWidth, false), str)
}

func newParseState(tabWidth int, plain bool) *parseState {
	return &parseState{style: tcell.StyleDefault, tabWidth: tabWidth, plain: plain}
}

// parseString parses the string into cells.
func parseString(st *parseState, str string) contents {
	lc := make(contents, 0, len(str))
	gr := newGraphemes(str)
	for gr.next() {
		r, cluster := gr.rune, gr.cluster
		switch {
		case r == '\x1b':
			// Escape sequence.
			if n, ok := parseEscape(st, str[gr.pos:]); ok {
				gr.skip(n)
				continue
			}
			// Unknown: drop the ESC itself.
			continue
		case r == '\r':
			continue
		case r == '\b':
			// Backspace: overstrike handling.
			if len(lc) == 0 {
				continue
			}
			st.bsFlag = true
			st.bsContent = lc[len(lc)-1]
			continue
		case r == '\t':
			if st.tabWidth > 0 {
				w := st.tabWidth - (len(lc) % st.tabWidth)
				for i := 0; i < w; i++ {
					lc = append(lc, content{mainc: ' ', width: 1, style: st.style})
				}
			} else if st.tabWidth < 0 {
				lc = append(lc, content{mainc: '\\', width: 1, style: st.style.Reverse(true)})
				lc = append(lc, content{mainc: 't', width: 1, style: st.style.Reverse(true)})
			}
			continue
		}
		c := content{style: st.style}
		if isControl(r) {
			c.mainc = ' '
			c.width = 1
			lc = appendContent(st, lc, c)
