		case 0:
			// Zero width: attach to the previous cell as combining.
			if len(lc) > 0 {
				prev := &lc[len(lc)-1]
				if prev.mainc == cellPlaceholder && len(lc) > 1 {
					prev = &lc[len(lc)-2]
				}
				prev.combc = append(prev.combc, r)
				prev.combc = append(prev.combc, cluster...)
			}
			continue
