}

// appendContent appends a cell, applying overstrike rules when a backspace
// preceded it.
func appendContent(st *parseState, lc contents, c content) contents {
	if !st.bsFlag {
		return append(lc, c)
	}
	st.bsFlag = false
	prev := st.bsContent
	// The last cell(s) are replaced.
	n := len(lc) - 1
	if n >= 0 && lc[n].mainc == cellPlaceholder && n > 0 {
		n--
	}
	if n < 0 {
		return append(lc, c)
	}
	lc = lc[:n]
	switch {
	case prev.mainc == c.mainc:
		c.style = applyStyle(c.style, st.overStrike)
	case prev.mainc == '_':
		c.style = applyStyle(c.style, st.overLine)
	case c.mainc == '_':
		c = prev
		c.style = applyStyle(c.style, st.overLine)
	}
	return append(lc, c)
}

// runeWidth returns the display width of a rune (with its grapheme cluster).
func runeWidth(r rune, cluster []rune) int {
	if r == 0 {
		return 0
	}
	if len(cluster) > 0 {
		// Emoji sequences with variation selectors or ZWJ are wide.
		for _, c := range cluster {
			if c == 0xFE0F || c == 0x200D {
				return 2
			}
		}
	}
	return runewidth.RuneWidth(r)
}

// graphemes iterates over a string yielding the base rune and any
// combining runes that follow.
type graphemes struct {
	str     string
	pos     int
	next0   int
	rune    rune
	cluster []rune
}

func newGraphemes(s string) *graphemes {
	return &graphemes{str: s}
}

func (g *graphemes) next() bool {
	if g.next0 >= len(g.str) {
		return false
	}
	g.pos = g.next0
	r, size := utf8.DecodeRuneInString(g.str[g.pos:])
	g.rune = r
	g.cluster = nil
	g.next0 = g.pos + size
	if r == '\x1b' || r == '\t' || r == '\b' || r == '\r' || r == utf8.RuneError && size == 1 {
		if r == utf8.RuneError {
			g.rune = utf8.RuneError
		}
		return true
	}
	// Gather following zero-width (combining) runes.
	for g.next0 < len(g.str) {
		r2, s2 := utf8.DecodeRuneInString(g.str[g.next0:])
		if r2 == utf8.RuneError && s2 == 1 {
			break
		}
		if isCombining(r2) {
			g.cluster = append(g.cluster, r2)
			g.next0 += s2
			continue
		}
		break
	}
	return true
}

// skip advances n bytes after the current rune position.
func (g *graphemes) skip(n int) {
	g.next0 = g.pos + n
}

func isCombining(r rune) bool {
	if r == 0x200D || r == 0xFE0F || r == 0xFE0E {
		return true
	}
	if r >= 0x1F3FB && r <= 0x1F3FF { // skin tone modifiers
		return true
	}
	if runewidth.RuneWidth(r) == 0 && r != 0 && !isControl(r) && r > 0x7f {
		return true
	}
	return false
}

// parseEscape parses an escape sequence starting at s[0] == ESC.
// It returns the number of bytes consumed and true on success.
func parseEscape(st *parseState, s string) (int, bool) {
	if len(s) < 2 {
		return len(s), true
	}
	switch s[1] {
	case '[':
		// CSI: ESC [ params final(0x40-0x7e)
		i := 2
		for i < len(s) {
			c := s[i]
			if c >= 0x40 && c <= 0x7e {
				if c == 'm' && !st.plain {
					st.style = applySGR(st.style, s[2:i])
				}
				return i + 1, true
			}
			if c < 0x20 || c > 0x3f {
				// Invalid in CSI; stop.
				return i, true
			}
			i++
		}
		return len(s), true
	case ']', 'P', 'X', '^', '_':
		// OSC / DCS / SOS / PM / APC: terminated by BEL or ST (ESC \).
		i := 2
		for i < len(s) {
			if s[i] == '\a' {
				return i + 1, true
			}
			if s[i] == '\x1b' {
				if i+1 < len(s) && s[i+1] == '\\' {
					return i + 2, true
				}
				return i, true
			}
			i++
		}
		return len(s), true
	case '(', ')', '*', '+', '-', '.', '/', '#', ' ', '%':
		if len(s) >= 3 {
			return 3, true
		}
		return len(s), true
	default:
		if s[1] >= 0x40 && s[1] <= 0x5f {
			return 2, true
		}
		return 2, true
	}
}

// applySGR applies the SGR parameters to the style.
func applySGR(style tcell.Style, params string) tcell.Style {
	if params == "" {
		return tcell.StyleDefault
	}
	fields := strings.Split(params, ";")
	for i := 0; i < len(fields); i++ {
		f := fields[i]
		sub := []string{f}
		if strings.Contains(f, ":") {
			sub = strings.Split(f, ":")
			f = sub[0]
		}
		n, err := strconv.Atoi(f)
		if err != nil {
			if f == "" {
				n = 0
			} else {
				continue
			}
		}
		switch {
		case n == 0:
			style = tcell.StyleDefault
		case n == 1:
			style = style.Bold(true)
		case n == 2:
			style = style.Dim(true)
		case n == 3:
			style = style.Italic(true)
		case n == 4:
			if len(sub) > 1 {
				switch sub[1] {
				case "0":
					style = style.Underline(false)
				case "1":
					style = style.Underline(tcell.UnderlineStyleSolid)
				case "2":
					style = style.Underline(tcell.UnderlineStyleDouble)
				case "3":
					style = style.Underline(tcell.UnderlineStyleCurly)
				case "4":
					style = style.Underline(tcell.UnderlineStyleDotted)
				case "5":
					style = style.Underline(tcell.UnderlineStyleDashed)
				default:
					style = style.Underline(true)
				}
			} else {
				style = style.Underline(true)
			}
		case n == 5 || n == 6:
			style = style.Blink(true)
		case n == 7:
			style = style.Reverse(true)
		case n == 8:
			// conceal: not supported
		case n == 9:
			style = style.StrikeThrough(true)
		case n == 21:
			style = style.Underline(tcell.UnderlineStyleDouble)
		case n == 22:
			style = style.Bold(false).Dim(false)
		case n == 23:
			style = style.Italic(false)
		case n == 24:
			style = style.Underline(false)
		case n == 25:
			style = style.Blink(false)
		case n == 27:
			style = style.Reverse(false)
		case n == 28:
		case n == 29:
			style = style.StrikeThrough(false)
		case n >= 30 && n <= 37:
			style = style.Foreground(tcell.PaletteColor(n - 30))
		case n == 38 || n == 48 || n == 58:
			var color tcell.Color
			var consumed int
			var ok bool
			if len(sub) > 1 {
				color, _, ok = parseExtColor(sub[1:])
			} else {
				color, consumed, ok = parseExtColor(fields[i+1:])
				i += consumed
			}
			if !ok {
				continue
			}
			switch n {
			case 38:
				style = style.Foreground(color)
			case 48:
				style = style.Background(color)
			case 58:
				style = style.Underline(color)
			}
		case n == 39:
			style = style.Foreground(tcell.ColorDefault)
		case n >= 40 && n <= 47:
			style = style.Background(tcell.PaletteColor(n - 40))
		case n == 49:
			style = style.Background(tcell.ColorDefault)
		case n == 53:
			// overline: not supported by tcell
		case n == 59:
			style = style.Underline(tcell.ColorDefault)
		case n >= 90 && n <= 97:
			style = style.Foreground(tcell.PaletteColor(n - 90 + 8))
		case n >= 100 && n <= 107:
			style = style.Background(tcell.PaletteColor(n - 100 + 8))
		}
	}
	return style
}

// parseExtColor parses "5;n" or "2;r;g;b" style parameters.
// It returns the color, the number of fields consumed and ok.
func parseExtColor(fields []string) (tcell.Color, int, bool) {
	if len(fields) == 0 {
		return 0, 0, false
	}
	switch fields[0] {
	case "5":
		if len(fields) < 2 {
			return 0, len(fields), false
		}
		n, err := strconv.Atoi(fields[1])
		if err != nil || n < 0 || n > 255 {
			return 0, 2, false
		}
		return tcell.PaletteColor(n), 2, true
	case "2":
		if len(fields) < 4 {
			return 0, len(fields), false
		}
		vals := [3]int32{}
		for j := 0; j < 3; j++ {
			n, err := strconv.Atoi(fields[1+j])
			if err != nil {
				return 0, 4, false
			}
			if n < 0 {
				n = 0
			}
			if n > 255 {
				n = 255
			}
			vals[j] = int32(n)
		}
		return tcell.NewRGBColor(vals[0], vals[1], vals[2]), 4, true
	}
	return 0, 1, false
}

// applyStyle overlays the non-default attributes of over onto base.
func applyStyle(base tcell.Style, over tcell.Style) tcell.Style {
	if over == tcell.StyleDefault {
		return base
	}
	fg, bg, attr := over.Decompose()
	if fg != tcell.ColorDefault {
		base = base.Foreground(fg)
	}
	if bg != tcell.ColorDefault {
		base = base.Background(bg)
	}
	if attr&tcell.AttrBold != 0 {
		base = base.Bold(true)
	}
	if attr&tcell.AttrBlink != 0 {
		base = base.Blink(true)
	}
	if attr&tcell.AttrDim != 0 {
		base = base.Dim(true)
	}
	if attr&tcell.AttrItalic != 0 {
		base = base.Italic(true)
	}
	if attr&tcell.AttrUnderline != 0 {
		base = base.Underline(true)
	}
	if attr&tcell.AttrStrikeThrough != 0 {
		base = base.StrikeThrough(true)
	}
	if attr&tcell.AttrReverse != 0 {
		base = base.Reverse(true)
	}
	return base
}

// String returns the plain text of the cells.
func (lc contents) String() string {
	var b strings.Builder
	for _, c := range lc {
		if c.mainc == cellPlaceholder {
			continue
		}
		b.WriteRune(c.mainc)
		for _, r := range c.combc {
			b.WriteRune(r)
		}
	}
	return b.String()
}

// widthPos returns the cell position of each byte position of the string
// built by StrToContents; used to map search match byte offsets to cells.
// It returns a slice where index i is the cell index of the i-th rune of the
// plain (non-escape) text.
func contentsRuneMap(lc contents) []int {
	m := make([]int, 0, len(lc)+1)
	for i, c := range lc {
		if c.mainc == cellPlaceholder {
			continue
		}
		m = append(m, i)
	}
	m = append(m, len(lc))
	return m
}
