}

// applySGR applies the SGR parameters to the style.
func applySGR(style tcell.Style, params string) tcell.Style {
	if params == "" {
		return tcell.StyleDefault
	}
	fields := strings.Split(params, ";")
	for i := 0; i < len(fields); i++ {
		f := fields[i]
		sub := []string{f}
		if strings.Contains(f, ":") {
			sub = strings.Split(f, ":")
			f = sub[0]
		}
		n, err := strconv.Atoi(f)
		if err != nil {
			if f == "" {
				n = 0
			} else {
				continue
			}
		}
		switch {
		case n == 0:
			style = tcell.StyleDefault
		case n == 1:
			style = style.Bold(true)
		case n == 2:
			style = style.Dim(true)
		case n == 3:
			style = style.Italic(true)
		case n == 4:
			if len(sub) > 1 {
				switch sub[1] {
				case "0":
					style = style.Underline(false)
				case "1":
					style = style.Underline(tcell.UnderlineStyleSolid)
				case "2":
					style = style.Underline(tcell.UnderlineStyleDouble)
				case "3":
					style = style.Underline(tcell.UnderlineStyleCurly)
				case "4":
					style = style.Underline(tcell.UnderlineStyleDotted)
				case "5":
					style = style.Underline(tcell.UnderlineStyleDashed)
				default:
					style = style.Underline(true)
				}
			} else {
				style = style.Underline(true)
			}
		case n == 5 || n == 6:
			style = style.Blink(true)
		case n == 7:
			style = style.Reverse(true)
		case n == 8:
			// conceal: not supported
		case n == 9:
			style = style.StrikeThrough(true)
		case n == 21:
			style = style.Underline(tcell.UnderlineStyleDouble)
		case n == 22:
			style = style.Bold(false).Dim(false)
		case n == 23:
			style = style.Italic(false)
		case n == 24:
			style = style.Underline(false)
		case n == 25:
			style = style.Blink(false)
		case n == 27:
			style = style.Reverse(false)
		case n == 28:
		case n == 29:
			style = style.StrikeThrough(false)
		case n >= 30 && n <= 37:
			style = style.Foreground(tcell.PaletteColor(n - 30))
		case n == 38 || n == 48 || n == 58:
			var color tcell.Color
			var consumed int
			var ok bool
			if len(sub) > 1 {
				color, _, ok = parseExtColor(sub[1:])
			} else {
				color, consumed, ok = parseExtColor(fields[i+1:])
				i += consumed
			}
			if !ok {
				continue
			}
			switch n {
			case 38:
				style = style.Foreground(color)
			case 48:
				style = style.Background(color)
			case 58:
				style = style.Underline(color)
			}
		case n == 39:
			style = style.Foreground(tcell.ColorDefault)
		case n >= 40 && n <= 47:
			style = style.Background(tcell.PaletteColor(n - 40))
		case n == 49:
			style = style.Background(tcell.ColorDefault)
		case n == 53:
			// overline: not supported by tcell
		case n == 59:
			style = style.Underline(tcell.ColorDefault)
		case n >= 90 && n <= 97:
			style = style.Foreground(tcell.PaletteColor(n - 90 + 8))
		case n >= 100 && n <= 107:
			style = style.Background(tcell.PaletteColor(n - 100 + 8))
		}
	}
	return style
}

// parseExtColor parses "5;n" or "2;r;g;b" style parameters.
// It returns the color, the number of fields consumed and ok.
func parseExtColor(fields []string) (tcell.Color, int, bool) {
	if len(fields) == 0 {
		return 0, 0, false
	}
	switch fields[0] {
	case "5":
		if len(fields) < 2 {
			return 0, len(fields), false
		}
		n, err := strconv.Atoi(fields[1])
		if err != nil || n < 0 || n > 255 {
			return 0, 2, false
		}
		return tcell.PaletteColor(n), 2, true
	case "2":
		if len(fields) < 4 {
			return 0, len(fields), false
		}
		vals := [3]int32{}
		for j := 0; j < 3; j++ {
			n, err := strconv.Atoi(fields[1+j])
			if err != nil {
				return 0, 4, false
			}
			if n < 0 {
				n = 0
			}
			if n > 255 {
				n = 255
			}
			vals[j] = int32(n)
		}
		return tcell.NewRGBColor(vals[0], vals[1], vals[2]), 4, true
	}
	return 0, 1, false
}

// applyStyle overlays the non-default attributes of over onto base.
func applyStyle(base tcell.Style, over tcell.Style) tcell.Style {
	if over == tcell.StyleDefault {
		return base
	}
	fg, bg, attr := over.Decompose()
	if fg != tcell.ColorDefault {
		base = base.Foreground(fg)
	}
	if bg != tcell.ColorDefault {
		base = base.Background(bg)
	}
	if attr&tcell.AttrBold != 0 {
		base = base.Bold(true)
	}
	if attr&tcell.AttrBlink != 0 {
		base = base.Blink(true)
	}
	if attr&tcell.AttrDim != 0 {
		base = base.Dim(true)
	}
	if attr&tcell.AttrItalic != 0 {
		base = base.Italic(true)
	}
	if attr&tcell.AttrUnderline != 0 {
		base = base.Underline(true)
	}
	if attr&tcell.AttrStrikeThrough != 0 {
		base = base.StrikeThrough(true)
	}
	if attr&tcell.AttrReverse != 0 {
		base = base.Reverse(true)
	}
	return base
}

// String returns the plain text of the cells.
func (lc contents) String() string {
	var b strings.Builder
	for _, c := range lc {
		if c.mainc == cellPlaceholder {
			continue
		}
		b.WriteRune(c.mainc)
		for _, r := range c.combc {
			b.WriteRune(r)
		}
	}
	return b.String()
}

// widthPos returns the cell position of each byte position of the string
// built by StrToContents; used to map search match byte offsets to cells.
// It returns a slice where index i is the cell index of the i-th rune of the
// plain (non-escape) text.
func contentsRuneMap(lc contents) []int {
	m := make([]int, 0, len(lc)+1)
	for i, c := range lc {
		if c.mainc == cellPlaceholder {
			continue
		}
		m = append(m, i)
	}
	m = append(m, len(lc))
	return m
}
EOF
