		rightAlign:    map[int]bool{},
	}
	m.RunTimeSettings.TabWidth = 8
	m.RunTimeSettings.MarkStyleWidth = 1
	m.RunTimeSettings.HScrollWidth = "10%"
	m.RunTimeSettings.SectionHeaderNum = 1
	m.RunTimeSettings.StatusLine = true
	m.RunTimeSettings.Converter = ConvEscaped
	m.RunTimeSettings.ColumnDelimiter = ","
	return m
}

// Lines

// BufEndNum returns the number of complete lines loaded.
func (m *Document) BufEndNum() int {
	m.mu.RLock()
	defer m.mu.RUnlock()
	return m.endNum
}

// BufEOF reports whether the document reached EOF.
func (m *Document) BufEOF() bool {
	return atomic.LoadInt32(&m.eof) == 1
}

// GetLine returns the raw line (without newline) for the line number.
func (m *Document) GetLine(n int) string {
	m.mu.RLock()
	defer m.mu.RUnlock()
	if n < 0 || n >= m.endNum {
		return ""
	}
	return m.lines[n]
}

// Line returns the line and whether it exists.
func (m *Document) Line(n int) (string, bool) {
	m.mu.RLock()
	defer m.mu.RUnlock()
	if n < 0 || n >= m.endNum {
		return "", false
	}
	return m.lines[n], true
}

// appendLine appends a line to the document.
func (m *Document) appendLine(line string) {
	m.mu.Lock()
	m.lines = append(m.lines, line)
	m.endNum = len(m.lines)
	m.mu.Unlock()
	atomic.StoreInt32(&m.changed, 1)
}

// appendBytes appends data read from the input (may contain partial lines).
func (m *Document) appendBytes(buf []byte) {
	m.mu.Lock()
	data := buf
	if len(m.partial) > 0 {
		data = append(m.partial, buf...)
		m.partial = nil
	}
	for {
		i := bytes.IndexByte(data, '\n')
		if i < 0 {
			break
		}
		m.lines = append(m.lines, string(data[:i]))
		data = data[i+1:]
	}
	if len(data) > 0 {
		m.partial = append([]byte{}, data...)
	}
	m.endNum = len(m.lines)
	m.mu.Unlock()
	atomic.StoreInt32(&m.changed, 1)
}

// flushPartial converts a trailing partial line into a complete line (EOF).
func (m *Document) flushPartial() {
	m.mu.Lock()
	if len(m.partial) > 0 {
		m.lines = append(m.lines, string(m.partial))
		m.partial = nil
		m.endNum = len(m.lines)
	}
	m.mu.Unlock()
	atomic.StoreInt32(&m.changed, 1)
}

// reset clears all lines.
func (m *Document) reset() {
	m.mu.Lock()
	m.lines = nil
	m.partial = nil
	m.endNum = 0
	m.mu.Unlock()
	atomic.StoreInt32(&m.eof, 0)
	m.clearCache()
	atomic.StoreInt32(&m.changed, 1)
}

func (m *Document) clearCache() {
	m.cacheMu.Lock()
	m.cache = map[int]contents{}
	m.cacheGen++
	m.cacheMu.Unlock()
}

// ReadAll reads all data from the reader asynchronously.
func (m *Document) ReadAll(r io.Reader) {
	go func() {
		m.readLoop(r)
	}()
}

// readLoop reads the reader until EOF.
func (m *Document) readLoop(r io.Reader) {
	br := bufio.NewReaderSize(r, 64*1024)
	buf := make([]byte, 64*1024)
	for {
		n, err := br.Read(buf)
		if n > 0 {
			m.appendBytes(buf[:n])
		}
		if err != nil {
			break
		}
	}
	m.flushPartial()
	atomic.StoreInt32(&m.eof, 1)
	atomic.StoreInt32(&m.changed, 1)
}

// readLoopFollow reads a seekable file and keeps reading new data (follow mode).
func (m *Document) readSync(r io.Reader) error {
	br := bufio.NewReaderSize(r, 64*1024)
	buf := make([]byte, 64*1024)
	for {
		n, err := br.Read(buf)
		if n > 0 {
			m.appendBytes(buf[:n])
		}
		if err != nil {
			if err == io.EOF {
				return nil
			}
			return err
		}
	}
}

// Marks

// addMark marks the line.
func (m *Document) addMark(ln int) {
	for _, v := range m.marked {
		if v == ln {
			return
		}
	}
	m.marked = append(m.marked, ln)
}

// removeMark removes the mark of the line.
func (m *Document) removeMark(ln int) bool {
	for i, v := range m.marked {
		if v == ln {
			m.marked = append(m.marked[:i], m.marked[i+1:]...)
			return true
		}
	}
	return false
}

func (m *Document) isMarked(ln int) bool {
	for _, v := range m.marked {
		if v == ln {
			return true
		}
	}
	return false
}

// getContents returns parsed contents for the line (cached).
func (m *Document) getContents(ln int) contents {
	m.cacheMu.Lock()
	if lc, ok := m.cache[ln]; ok {
		m.cacheMu.Unlock()
		return lc
	}
	m.cacheMu.Unlock()
	str, ok := m.Line(ln)
	if !ok {
		return nil
	}
	lc := m.parseLine(str)
	m.cacheMu.Lock()
	if len(m.cache) > 10000 {
		m.cache = map[int]contents{}
	}
	m.cache[ln] = lc
	m.cacheMu.Unlock()
	return lc
}

// parseLine converts the raw line into cells according to the settings.
func (m *Document) parseLine(str string) contents {
	st := newParseState(m.RunTimeSettings.TabWidth, m.RunTimeSettings.PlainMode)
	st.overStrike = m.overStrikeStyle()
	st.overLine = m.overLineStyle()
	if m.RunTimeSettings.Converter == ConvRaw {
		return parseRaw(st, str)
	}
	lc := parseString(st, str)
	if m.RunTimeSettings.Converter == ConvAlign {
		return lc
	}
	return lc
}

// parseRaw renders escape sequences literally (as "^[" cells).
func parseRaw(st *parseState, str string) contents {
	var b bytes.Buffer
	for i := 0; i < len(str); i++ {
		if str[i] == '\x1b' {
			b.WriteString("^[")
			continue
		}
		b.WriteByte(str[i])
	}
	st.plain = true
	return parseString(st, b.String())
}

func (m *Document) overStrikeStyle() tcell.Style {
	return m.RunTimeSettings.Style.OverStrike
}

func (m *Document) overLineStyle() tcell.Style {
	return m.RunTimeSettings.Style.OverLine
}

// LineCount returns the number of lines (complete lines).
func (m *Document) LineCount() int { return m.BufEndNum() }

// isEmpty reports whether the document has no lines.
func (m *Document) isEmpty() bool { return m.BufEndNum() == 0 }

// visibleName returns the name shown on the status line.
func (m *Document) visibleName() string {
	if m.Caption != "" {
		return m.Caption
	}
	return m.FileName
}

// setDelimiter compiles the column delimiter.
func (m *Document) setDelimiter(delm string) {
	m.RunTimeSettings.ColumnDelimiter = delm
	m.RunTimeSettings.ColumnDelimiterReg = compileDelimiter(delm)
}

// compileDelimiter returns a regexp if the delimiter looks like a regexp
// (enclosed in slashes), otherwise nil.
func compileDelimiter(delm string) *regexp.Regexp {
	if len(delm) > 2 && delm[0] == '/' && delm[len(delm)-1] == '/' {
		re, err := regexp.Compile(delm[1 : len(delm)-1])
		if err == nil {
			return re
		}
	}
	return nil
}

// setSectionDelimiter compiles the section delimiter.
func (m *Document) setSectionDelimiter(delm string) {
	m.RunTimeSettings.SectionDelimiter = delm
	m.SectionDelimiterReg = nil
	if delm == "" {
		return
	}
	re, err := regexp.Compile(delm)
	if err != nil {
		return
	}
	m.SectionDelimiterReg = re
}

// close closes the underlying file.
func (m *Document) close() error {
	if m.file != nil {
		err := m.file.Close()
		m.file = nil
		return err
	}
	return nil
}
EOF
echo ok

