package oviewer

import (
	"regexp"
	"strings"
	"unicode"
)

// Searcher is the interface for searching lines.
type Searcher interface {
	// Match reports whether the string matches.
	Match(s string) bool
	// FindAll returns the [start,end) rune ranges of all matches.
	FindAll(s string) [][2]int
	// String returns the search word.
	String() string
}

// NewSearcher returns a searcher for the word with the given options.
func NewSearcher(word string, caseSensitive, smartCase, regexpMode bool) Searcher {
	if word == "" {
		return nil
	}
	cs := caseSensitive
	if smartCase && !caseSensitive {
		cs = hasUpper(word)
	}
	if regexpMode {
		pat := word
		if !cs {
			pat = "(?i)" + pat
		}
		re, err := regexp.Compile(pat)
		if err != nil {
			// fall back to literal search
			return newLiteralSearcher(word, cs)
		}
		return &regexpSearcher{word: word, re: re}
	}
	return newLiteralSearcher(word, cs)
}

func hasUpper(s string) bool {
	for _, r := range s {
		if unicode.IsUpper(r) {
			return true
		}
	}
	return false
}

type literalSearcher struct {
	word   string
	lower  string
	cs     bool
}

func newLiteralSearcher(word string, cs bool) Searcher {
	return &literalSearcher{word: word, lower: strings.ToLower(word), cs: cs}
}

func (s *literalSearcher) String() string { return s.word }

func (s *literalSearcher) Match(str string) bool {
	if s.cs {
		return strings.Contains(str, s.word)
	}
	return strings.Contains(strings.ToLower(str), s.lower)
}

func (s *literalSearcher) FindAll(str string) [][2]int {
	target := str
	word := s.word
	if !s.cs {
		target = strings.ToLower(str)
		word = s.lower
	}
	var res [][2]int
	if word == "" {
