// NewRoot creates a Root with the given documents.
func NewRoot(cfg Config, kb KeyBind, docs ...*Document) (*Root, error) {
	if len(docs) == 0 {
		return nil, ErrNotFound
	}
	root := &Root{
		Config:   cfg,
		keyBind:  kb,
		DocList:  docs,
		Doc:      docs[0],
		input:    NewInput(),
		statusLine: true,
	}
	root.general = settingsFromConfig(cfg)
	for _, m := range docs {
		root.applyGeneralSettings(m)
	}
