	s.Prompt.InvertColor = true
	s.Prompt.ProcessOfCount = true
	s.Prompt.NormalCursor = 0
	s.Prompt.InputCursor = 1
	if cfg.StyleOverStrike != nil {
		s.Style.OverStrike = ToTcellStyle(*cfg.StyleOverStrike)
	}
	if cfg.StyleOverLine != nil {
		s.Style.OverLine = ToTcellStyle(*cfg.StyleOverLine)
	}
	applyRunTime(&s, cfg.General)
	if cfg.ViewMode != "" {
		if m, ok := cfg.Mode[cfg.ViewMode]; ok {
