package oviewer

import (
	"context"
	"errors"
	"fmt"
	"log"
	"os"
	"strings"
	"sync"
	"time"

	"github.com/gdamore/tcell/v2"
)

// Root is the top level structure of the viewer.
type Root struct {
	Screen tcell.Screen

	// Doc is the current document.
	Doc *Document
	// DocList is the list of documents.
	DocList []*Document
	// CurrentDoc is the index of the current document.
	CurrentDoc int

	helpDoc *Document
	logDoc  *Document

	// Config holds the configuration.
	Config Config
	// general holds the resolved general (default) settings for new documents.
	general DocSettings
	// keyBind is the configured key bindings.
	keyBind KeyBind
	keyMap   keyMap
	inputMap keyMap

	// input is the current input state.
	input *Input

	// message is shown on the status line.
	message string
	// scr is the computed screen layout.
	scr screenLayout

	// searcher is the current search.
	searcher Searcher
	searchWord string

	// quit flags
	quitSmall     bool
	writeOriginal bool
	// skipDraw suppresses drawing (e.g. during suspend).
	skipDraw bool

	// mouse
	mouseSelect  bool
	mousePressed bool
	mouseRectangle bool
	x1, y1, x2, y2 int

	// followAll
	followAll bool

	// cancel function for background tasks
	cancelFunc context.CancelFunc
	cancelKeys []string

	// mu protects document list manipulation.
	mu sync.Mutex

	// forceScreen draws even when stdout is not a terminal.
	forceScreen bool

	// FollowAll notifications.
	changedDoc int

	// ruler/status flags
	statusLine bool

	// prevent event storms
	drawing bool

	// writeOriginal options
	BeforeWriteOriginal int
	AfterWriteOriginal  int
	IsWriteOriginal     bool
	// QuitSmall quits if the document fits on one screen.
	QuitSmall bool

	// pattern applied at startup
	initPattern string
	// mouse enabled
	mouseEnabled bool

	// ansi: tab for the help's table
	done bool

	// For "sync" of filter documents.
	filterCount int

	// debug
	debug bool

	// timers
	lastUpdate time.Time

	// Clipboard contents for paste.
	clipboard string

	// sticky follow
	stickyFollow bool

	// screen size
	width, height int
}

// Errors.
var (
	ErrOutOfRange   = errors.New("out of range")
	ErrNotFound     = errors.New("not found")
	ErrCancel       = errors.New("cancel")
	ErrInvalidNumber = errors.New("invalid number")
	ErrFailedKeyBind = errors.New("failed to set keybind")
	ErrSignalCatch  = errors.New("signal catch")
	ErrAlreadyClosed = errors.New("already closed")
	ErrEOFReached   = errors.New("EOF reached")
	ErrNoColumn     = errors.New("no column")
	ErrNoDelimiter  = errors.New("no delimiter")
	ErrNoMoreSection = errors.New("no more section")
	ErrOverScreen   = errors.New("over screen")
	ErrMissingFile  = errors.New("missing filename")
	ErrIsDirectory  = errors.New("is a directory")
	ErrNotTerminal  = errors.New("not a terminal")
	ErrPreventReload = errors.New("prevent reload")
	ErrNoMatch      = errors.New("no match")
	ErrNotInMemory  = errors.New("not in memory")
	ErrInvalidDocument = errors.New("invalid document")
)

// Custom events.
type eventAppQuit struct{ tcell.EventTime }
type eventUpdate struct{ tcell.EventTime }
type eventDocument struct {
	tcell.EventTime
	docNum int
}
type eventReload struct {
	tcell.EventTime
	doc *Document
}

// NewRoot creates a Root with the given documents.
func NewRoot(cfg Config, kb KeyBind, docs ...*Document) (*Root, error) {
	if len(docs) == 0 {
		return nil, ErrNotFound
	}
	root := &Root{
		Config:   cfg,
		keyBind:  kb,
		DocList:  docs,
		Doc:      docs[0],
		input:    NewInput(),
		statusLine: true,
	}
	root.general = settingsFromConfig(cfg)
	for _, m := range docs {
		root.applyGeneralSettings(m)
	}
	root.QuitSmall = cfg.QuitSmall
	root.IsWriteOriginal = cfg.IsWriteOriginal
	root.BeforeWriteOriginal = cfg.BeforeWriteOriginal
	root.AfterWriteOriginal = cfg.AfterWriteOriginal
	root.mouseEnabled = !cfg.DisableMouse
	root.debug = cfg.Debug
	return root, nil
}

// settingsFromConfig builds the DocSettings from the general config
// (and the selected view mode).
func settingsFromConfig(cfg Config) DocSettings {
	s := DocSettings{
		TabWidth:         8,
		MarkStyleWidth:   1,
		HScrollWidth:     "10%",
		SectionHeaderNum: 1,
		StatusLine:       true,
		Converter:        ConvEscaped,
		ColumnDelimiter:  ",",
		WrapMode:         true,
		Style:            defaultStyles(),
	}
	s.Prompt.ShowFilename = true
	s.Prompt.InvertColor = true
	s.Prompt.ProcessOfCount = true
	s.Prompt.NormalCursor = 0
	s.Prompt.InputCursor = 1
	if cfg.StyleOverStrike != nil {
		s.Style.OverStrike = ToTcellStyle(*cfg.StyleOverStrike)
	}
	if cfg.StyleOverLine != nil {
		s.Style.OverLine = ToTcellStyle(*cfg.StyleOverLine)
	}
	applyRunTime(&s, cfg.General)
	if cfg.ViewMode != "" {
		if m, ok := cfg.Mode[cfg.ViewMode]; ok {
			applyRunTime(&s, m)
		}
	}
	return s
}

// applyRunTime overlays the specified (non-nil) settings.
func applyRunTime(s *DocSettings, r RunTimeSettings) {
	setInt := func(dst *int, v *int) {
		if v != nil {
			*dst = *v
		}
	}
	setBool := func(dst *bool, v *bool) {
		if v != nil {
			*dst = *v
		}
	}
	setInt(&s.TabWidth, r.TabWidth)
	setInt(&s.Header, r.Header)
	setInt(&s.SkipLines, r.SkipLines)
	setInt(&s.VerticalHeader, r.VerticalHeader)
	setInt(&s.HeaderColumn, r.HeaderColumn)
	setInt(&s.WatchInterval, r.WatchInterval)
	setInt(&s.MarkStyleWidth, r.MarkStyleWidth)
	setInt(&s.SectionStartPosition, r.SectionStartPosition)
	setInt(&s.SectionHeaderNum, r.SectionHeaderNum)
	setInt(&s.RulerType, r.RulerType)
	setInt(&s.VScrollLines, r.VScrollLines)
	if r.HScrollWidth != "" {
		s.HScrollWidth = r.HScrollWidth
	}
	if r.JumpTarget != "" {
		s.JumpTarget = r.JumpTarget
	}
	if r.ColumnDelimiter != nil {
		s.ColumnDelimiter = *r.ColumnDelimiter
	}
	if r.SectionDelimiter != nil {
		s.SectionDelimiter = *r.SectionDelimiter
	}
	if r.Caption != "" {
		s.Caption = r.Caption
	}
	if r.Converter != "" {
		s.Converter = r.Converter
	}
	if r.MultiColorWords != nil {
		s.MultiColorWords = r.MultiColorWords
	}
	setBool(&s.AlternateRows, r.AlternateRows)
	setBool(&s.ColumnMode, r.ColumnMode)
	setBool(&s.ColumnWidth, r.ColumnWidth)
	setBool(&s.ColumnRainbow, r.ColumnRainbow)
	setBool(&s.LineNumMode, r.LineNumMode)
	setBool(&s.WrapMode, r.WrapMode)
	setBool(&s.PlainMode, r.PlainMode)
	setBool(&s.SectionHeader, r.SectionHeader)
	setBool(&s.HideOtherSection, r.HideOtherSection)
	setBool(&s.StatusLine, r.StatusLine)
	setBool(&s.FollowMode, r.FollowMode)
	setBool(&s.FollowAll, r.FollowAll)
	setBool(&s.FollowSection, r.FollowSection)
	setBool(&s.FollowName, r.FollowName)
	setBool(&s.Prompt.ShowFilename, r.Prompt.Normal.ShowFilename)
	setBool(&s.Prompt.InvertColor, r.Prompt.Normal.InvertColor)
	setBool(&s.Prompt.ProcessOfCount, r.Prompt.Normal.ProcessOfCount)
	setInt(&s.Prompt.NormalCursor, r.Prompt.Normal.CursorType)
	setInt(&s.Prompt.InputCursor, r.Prompt.Input.CursorType)
	s.Style = applyStyleConfig(s.Style, r.Style)
}

// applyGeneralSettings applies the general settings to the document.
func (root *Root) applyGeneralSettings(m *Document) {
	s := root.general
	m.RunTimeSettings = s
	m.setDelimiter(s.ColumnDelimiter)
	m.setSectionDelimiter(s.SectionDelimiter)
	m.RunTimeSettings.HScrollWidthNum = 0
	m.FollowMode = s.FollowMode
	m.FollowSection = s.FollowSection
	m.FollowName = s.FollowName
	if s.Caption != "" {
		m.Caption = s.Caption
	}
	m.setJumpTarget(s.JumpTarget)
	m.clearCache()
}

// SetKeyBind builds the key maps from the key bindings.
func (root *Root) setKeyBind() error {
	km, err := buildKeyMap(root.keyBind, func(a string) bool { return !isInputAction(a) })
	if err != nil {
		return err
	}
	im, err := buildKeyMap(root.keyBind, isInputAction)
	if err != nil {
		return err
	}
	root.keyMap = km
	root.inputMap = im
	root.cancelKeys = root.keyBind[actionCancel]
	return nil
}

// Run starts the viewer.
func (root *Root) Run() error {
	if err := root.setKeyBind(); err != nil {
		return err
	}
	screen, err := newScreen()
	if err != nil {
		return err
	}
	if err := screen.Init(); err != nil {
		return fmt.Errorf("Screen.Init(): %w", err)
	}
	root.Screen = screen
	defer root.Close()

	if root.mouseEnabled {
		screen.EnableMouse(tcell.MouseDragEvents)
	}
	root.setupLog()
	root.width, root.height = screen.Size()
	root.prepareDocsStartup()

	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()
	go root.updateLoop(ctx)

	if root.Config.SetTerminalTitle {
		root.setTitle()
	}

	root.draw()
	for {
		ev := root.Screen.PollEvent()
		if ev == nil {
			return nil
		}
		quit := root.handleEvent(ev)
		if quit {
			break
		}
		root.draw()
	}
	return root.exitWrite()
}

// handleEvent dispatches a tcell event. It returns true when the viewer should quit.
func (root *Root) handleEvent(ev tcell.Event) bool {
	switch ev := ev.(type) {
	case *eventAppQuit:
		return true
	case *eventUpdate:
		root.updateDocs()
	case *eventDocument:
		root.setDocument(ev.docNum)
	case *eventReload:
		root.reloadDoc(ev.doc)
	case *tcell.EventResize:
		root.width, root.height = root.Screen.Size()
		root.Screen.Sync()
	case *tcell.EventKey:
		root.keyEvent(ev)
	case *tcell.EventMouse:
		root.mouseEvent(ev)
	case *tcell.EventPaste:
		root.pasteEvent(ev)
	case *tcell.EventInterrupt:
	}
	return root.done
}

// updateLoop posts update events while documents are loading or in follow mode.
func (root *Root) updateLoop(ctx context.Context) {
	tick := time.NewTicker(50 * time.Millisecond)
	defer tick.Stop()
	for {
		select {
		case <-ctx.Done():
			return
		case <-tick.C:
			changed := false
			root.mu.Lock()
			docs := append([]*Document{}, root.DocList...)
			if root.helpDoc != nil {
				docs = append(docs, root.helpDoc)
			}
			if root.logDoc != nil {
				docs = append(docs, root.logDoc)
			}
			root.mu.Unlock()
			for _, m := range docs {
				if m.swapChanged() {
					changed = true
				}
			}
			if changed {
				root.Screen.PostEvent(&eventUpdate{})
			}
		}
	}
}

// swapChanged returns the changed flag and clears it.
func (m *Document) swapChanged() bool {
	m.mu.Lock()
	defer m.mu.Unlock()
	c := m.changed == 1
	m.changed = 0
	return c
}

// updateDocs handles document updates (follow mode, etc).
func (root *Root) updateDocs() {
	if root.followAll {
		root.followAllUpdate()
	}
	for _, m := range root.DocList {
		if m.FollowMode || m.docType == docLog {
			m.followUpdate(root)
		}
	}
	if root.logDoc != nil {
		root.logDoc.followUpdate(root)
	}
	if root.QuitSmall && root.Doc.BufEOF() {
		if root.docSmall() {
			root.IsWriteOriginal = true
			root.done = true
		}
	}
}

// followUpdate moves to the bottom when new lines arrive in follow mode.
func (m *Document) followUpdate(root *Root) {
	num := m.BufEndNum()
	if num == m.latestNum {
		return
	}
	m.latestNum = num
	if m.FollowSection {
		root.tailSection(m)
		return
	}
	root.moveBottomDoc(m)
}

// Close finalizes the screen.
func (root *Root) Close() {
	if root.Screen != nil {
		root.Screen.Fini()
		root.Screen = nil
	}
}

// Quit requests to quit.
func (root *Root) Quit() {
	root.done = true
}

// setMessage sets the status message.
func (root *Root) setMessage(msg string) {
	root.message = msg
}

func (root *Root) setMessagef(format string, a ...any) {
	root.message = fmt.Sprintf(format, a...)
}

// setMessageLog sets the message and also logs it.
func (root *Root) setMessageLog(msg string) {
	root.message = msg
	log.Println(msg)
}

func (root *Root) setMessageLogf(format string, a ...any) {
	root.setMessageLog(fmt.Sprintf(format, a...))
}

// debugMessage logs only in debug mode.
func (root *Root) debugMessage(msg string) {
	if root.debug {
		log.Println(msg)
	}
}

// setupLog redirects the log output to the log document.
func (root *Root) setupLog() {
	if root.logDoc == nil {
		root.logDoc = newLogDoc()
	}
	log.SetOutput(root.logDoc)
	log.SetFlags(log.LstdFlags)
}

// newLogDoc creates the log document.
func newLogDoc() *Document {
	m := NewDocument()
	m.FileName = "Log"
	m.docType = docLog
	m.FollowMode = true
	m.preventReload = true
	m.RunTimeSettings.WrapMode = false
	m.RunTimeSettings.Style = defaultStyles()
	m.RunTimeSettings.Prompt.ShowFilename = true
	m.RunTimeSettings.Prompt.InvertColor = true
	m.RunTimeSettings.Prompt.ProcessOfCount = true
	m.RunTimeSettings.Prompt.InputCursor = 1
	m.RunTimeSettings.StatusLine = true
	m.RunTimeSettings.HScrollWidth = "10%"
	m.RunTimeSettings.Converter = ConvEscaped
	m.RunTimeSettings.ColumnDelimiter = ","
	m.initialWrapQuirk = true
	return m
}

// Write implements io.Writer for the log document.
func (m *Document) Write(p []byte) (int, error) {
	m.appendBytes(p)
	return len(p), nil
}

// setTitle sets the terminal title.
func (root *Root) setTitle() {
	if root.Screen == nil {
		return
	}
	root.Screen.SetTitle(root.Doc.visibleName())
}

// prepareDocsStartup finalizes the documents before the first draw.
func (root *Root) prepareDocsStartup() {
	for _, m := range root.DocList {
		if m.RunTimeSettings.FollowAll {
			root.followAll = true
		}
	}
	if root.initPattern != "" {
		root.searchWord = root.initPattern
	}
}

// docSmall reports whether the current document fits on one screen.
func (root *Root) docSmall() bool {
	m := root.Doc
	if !m.BufEOF() {
		return false
	}
	root.prepareScreen()
	height := root.scr.bodyRows()
	width := root.scr.bodyWidth()
	rows := 0
	for i := 0; i < m.BufEndNum(); i++ {
		lc := m.getContents(i)
		if m.RunTimeSettings.WrapMode {
			rows += wrappedRows(lc, width)
		} else {
			rows++
		}
		if rows > height {
			return false
		}
	}
	return true
}

// exitWrite writes the screen contents to stdout on exit if requested.
func (root *Root) exitWrite() error {
	if !root.IsWriteOriginal {
		return nil
	}
	return root.writeOriginalOut(os.Stdout)
}

// pasteEvent handles bracketed paste.
func (root *Root) pasteEvent(ev *tcell.EventPaste) {
	_ = ev
}

// keyEvent dispatches a key event.
func (root *Root) keyEvent(ev *tcell.EventKey) {
	if root.input.mode != Normal {
		root.inputKeyEvent(ev)
		return
	}
	ke := keyEventFromTcell(ev)
	action, ok := root.keyMap[ke]
	if !ok {
		return
	}
	root.doAction(action)
}

// docNumString returns the "[n]" prefix when multiple documents are open.
func (root *Root) docNumString() string {
	if len(root.DocList) > 1 {
		return fmt.Sprintf("[%d]", root.CurrentDoc)
	}
	return ""
}

// statusName returns the document name part of the status line.
func (root *Root) statusName(m *Document) string {
	var b strings.Builder
	if m.docType == docLog || m.docType == docHelp {
		if m.FollowMode && m.docType == docLog {
			b.WriteString("(Follow Mode)")
		}
		b.WriteString(m.FileName)
		b.WriteString(":")
		return b.String()
	}
	if root.followAll {
		b.WriteString("(Follow All)")
	} else if m.FollowMode {
		if m.FollowSection {
			b.WriteString("(Follow Section)")
		} else if m.FollowName {
			b.WriteString("(Follow Name)")
		} else {
			b.WriteString("(Follow Mode)")
		}
	}
	if m.WatchMode {
		b.WriteString("(Watch)")
	}
	b.WriteString(root.docNumString())
	b.WriteString(m.visibleName())
	b.WriteString(":")
	return b.String()
}
EOF
echo ok

