package oviewer

import (
	"fmt"
	"strconv"
	"strings"

	"github.com/gdamore/tcell/v2"
)

// lineNumber identifies the content displayed on a screen row.
type lineNumber struct {
	number int // logical line number (0-based)
	wrap   int // start cell offset within the line (wrap mode)
	valid  bool
	eof    bool // the EOF marker row
}

// screenLayout holds the computed layout of the screen.
type screenLayout struct {
	vWidth  int
	vHeight int
	// startX is the x position where line contents start (after line numbers).
	startX int
	// headerLN/headerEnd is the range of header lines.
	headerLN  int
	headerEnd int
	// sectionHeaderLN/sectionHeaderEnd is the range of section header lines.
	sectionHeaderLN  int
	sectionHeaderEnd int
	// headerRows is the number of rows used by header + section header.
	headerRows int
	// rulerRows is 1 when a ruler is displayed.
	rulerRows int
	// rows maps each screen row to its content.
	rows []lineNumber
	// statusRow is the row of the status line (-1 if none).
	statusRow int
	// bodyRowsCount is the number of rows available to the body.
	bodyRowsCount int
	// bottomLN/bottomLX is the position of the last body row.
	bottomLN int
	bottomLX int
	// lineNumWidth is the width of the line number area (0 when off).
	lineNumWidth int
	// startY is the first row of the document area (after ruler).
	startY int
}

func (s *screenLayout) bodyRows() int  { return s.bodyRowsCount }
func (s *screenLayout) bodyWidth() int { return s.vWidth - s.startX }

// wrapStarts returns the start cell index of each wrapped row of lc for the
// given width. The slice always has at least one element.
func wrapStarts(lc contents, width int) []int {
	if width <= 0 {
		return []int{0}
	}
	starts := []int{0}
	x := 0
	for i := 0; i < len(lc); i++ {
		w := lc[i].width
		if w == 0 {
			// placeholder cell
			x++
			continue
		}
		if x+w > width {
			starts = append(starts, i)
			x = 0
		}
		x += w
		if x >= width && i+1 < len(lc) {
			starts = append(starts, i+1)
			x = 0
		}
	}
	return starts
}

// wrappedRows returns the number of rows needed to display lc.
func wrappedRows(lc contents, width int) int {
	return len(wrapStarts(lc, width))
}

// nextWrap returns the start of the next wrapped row after lx (or -1 if none).
func nextWrap(lc contents, width int, lx int) int {
	starts := wrapStarts(lc, width)
	for _, s := range starts {
		if s > lx {
			return s
		}
	}
	return -1
}

// prevWrap returns the start of the wrapped row before lx (or -1 if lx is 0).
func prevWrap(lc contents, width int, lx int) int {
	starts := wrapStarts(lc, width)
	prev := -1
	for _, s := range starts {
		if s >= lx {
			break
		}
		prev = s
	}
	return prev
}

// lastWrap returns the start of the last wrapped row.
func lastWrap(lc contents, width int) int {
	starts := wrapStarts(lc, width)
	return starts[len(starts)-1]
}

// prepareScreen computes the layout for the current document.
func (root *Root) prepareScreen() {
	m := root.Doc
	scr := &root.scr
	scr.vWidth, scr.vHeight = root.width, root.height
	if scr.vHeight <= 0 || scr.vWidth <= 0 {
		return
	}
	// status line
	if m.RunTimeSettings.StatusLine {
		scr.statusRow = scr.vHeight - 1
	} else {
		scr.statusRow = -1
	}
	docRows := scr.vHeight
	if scr.statusRow >= 0 {
		docRows--
	}
	scr.rulerRows = 0
	if m.RunTimeSettings.RulerType > 0 {
		scr.rulerRows = 1
	}
	scr.startY = scr.rulerRows
	docRows -= scr.rulerRows
	if docRows < 0 {
		docRows = 0
	}

	// line number width
	scr.lineNumWidth = 0
	scr.startX = 0
	if m.RunTimeSettings.LineNumMode {
		digits := len(strconv.Itoa(m.BufEndNum()))
		scr.lineNumWidth = digits
		scr.startX = digits + 1
	}
	scr.startX += root.markWidth(m)

	// header
	skip := m.RunTimeSettings.SkipLines
	scr.headerLN = skip
	scr.headerEnd = skip + m.RunTimeSettings.Header
	// section header
	scr.sectionHeaderLN = -1
	scr.sectionHeaderEnd = -1
	if m.RunTimeSettings.SectionHeader && m.SectionDelimiterReg != nil {
		sln := root.sectionHeaderStart(m)
		if sln >= 0 {
			scr.sectionHeaderLN = sln
			scr.sectionHeaderEnd = sln + m.RunTimeSettings.SectionHeaderNum
		}
	}

	width := scr.bodyWidth()
	rows := make([]lineNumber, 0, docRows)
	// header rows
	for ln := scr.headerLN; ln < scr.headerEnd && len(rows) < docRows; ln++ {
		rows = root.appendLineRows(rows, m, ln, 0, width, docRows)
	}
	for ln := scr.sectionHeaderLN; ln >= 0 && ln < scr.sectionHeaderEnd && len(rows) < docRows; ln++ {
		if ln < scr.headerEnd && ln >= scr.headerLN {
			continue
		}
		rows = root.appendLineRows(rows, m, ln, 0, width, docRows)
	}
	scr.headerRows = len(rows)
	scr.bodyRowsCount = docRows - scr.headerRows
	if scr.bodyRowsCount < 0 {
		scr.bodyRowsCount = 0
	}
	// body rows
	ln := m.topLN
	lx := m.topLX
	endNum := m.BufEndNum()
	for len(rows) < docRows {
		if ln >= endNum {
			if m.BufEOF() {
				rows = append(rows, lineNumber{number: ln, eof: true})
			} else {
				rows = append(rows, lineNumber{number: ln})
			}
			ln++
			continue
		}
		if ln < 0 {
			rows = append(rows, lineNumber{number: ln, eof: true})
			ln++
			continue
		}
		if !m.RunTimeSettings.WrapMode {
			rows = append(rows, lineNumber{number: ln, wrap: 0, valid: true})
			ln++
			continue
		}
		lc := m.getContents(ln)
		starts := wrapStarts(lc, width)
		started := false
		for _, s := range starts {
			if !started {
				if s < lx {
					continue
				}
				started = true
			}
			if len(rows) >= docRows {
				break
			}
			rows = append(rows, lineNumber{number: ln, wrap: s, valid: true})
		}
		if !started {
			// lx beyond the line; treat as the last wrap
			rows = append(rows, lineNumber{number: ln, wrap: starts[len(starts)-1], valid: true})
		}
		ln++
		lx = 0
	}
	scr.rows = rows
	// bottom position
	if len(rows) > 0 {
		last := rows[len(rows)-1]
		scr.bottomLN = last.number
		scr.bottomLX = last.wrap
	}
}

// appendLineRows appends the rows for the line (wrapped if needed).
func (root *Root) appendLineRows(rows []lineNumber, m *Document, ln int, lx int, width int, max int) []lineNumber {
	if !m.RunTimeSettings.WrapMode {
		return append(rows, lineNumber{number: ln, wrap: 0, valid: true})
	}
	lc := m.getContents(ln)
	starts := wrapStarts(lc, width)
	for _, s := range starts {
		if s < lx {
			continue
		}
		if len(rows) >= max {
			break
		}
		rows = append(rows, lineNumber{number: ln, wrap: s, valid: true})
	}
	return rows
}

// markWidth returns the width used by the mark indicator (0 for now).
func (root *Root) markWidth(m *Document) int {
	return 0
}

// sectionHeaderStart returns the line number of the section header for the
// current top position, or -1.
func (root *Root) sectionHeaderStart(m *Document) int {
	top := m.topLN
	if top <= m.RunTimeSettings.Header+m.RunTimeSettings.SkipLines {
		return -1
	}
	start := m.RunTimeSettings.SectionStartPosition
	// Search backwards for the delimiter from top-1 (the delimiter line
	// itself at top would be displayed normally).
	for ln := top - 1; ln >= m.RunTimeSettings.SkipLines+m.RunTimeSettings.Header; ln-- {
		if m.isSectionDelimiter(ln) {
			sln := ln + start
			if sln >= top {
				return -1
			}
			return sln
		}
	}
	return -1
}

// isSectionDelimiter reports whether the line matches the section delimiter.
func (m *Document) isSectionDelimiter(ln int) bool {
	if m.SectionDelimiterReg == nil {
		return false
	}
	str, ok := m.Line(ln)
	if !ok {
		return false
	}
	return m.SectionDelimiterReg.MatchString(stripEscape(str))
}

// draw renders the whole screen.
func (root *Root) draw() {
	if root.skipDraw || root.Screen == nil {
		return
	}
	m := root.Doc
	root.resetScreen()
	root.prepareScreen()
	scr := &root.scr
	if scr.vHeight <= 0 || scr.vWidth <= 0 {
		root.Screen.Show()
		return
	}
	// clear
	root.Screen.Clear()

	if scr.rulerRows > 0 {
		root.drawRuler()
	}
	root.drawRows(m)
	if scr.statusRow >= 0 {
		root.drawStatus()
	}
	root.Screen.Show()
}

// resetScreen refreshes the size.
func (root *Root) resetScreen() {
	root.width, root.height = root.Screen.Size()
}

// drawRows draws the document rows.
func (root *Root) drawRows(m *Document) {
	scr := &root.scr
	width := scr.bodyWidth()
	// Search highlighting.
	var searcher Searcher
	if root.input.mode == Normal || !root.input.isSearchMode() {
		searcher = root.searcher
	} else {
		searcher = root.searcher
	}
	for row, ln := range scr.rows {
		y := scr.startY + row
		isHeader := row < scr.headerRows
		if ln.eof {
			root.drawEOF(y, ln.number)
			continue
		}
		if !ln.valid {
			continue
		}
		lc := m.getContents(ln.number)
		lineStyle := root.lineStyle(m, ln.number, isHeader)
		// fill row
		root.fillRow(y, lineStyle)
		// line number
		if scr.lineNumWidth > 0 {
			root.drawLineNumber(m, y, ln, isHeader)
		}
		// decorate contents
		dc := root.decorateContents(m, ln.number, lc, searcher, isHeader)
		if isHeader {
			root.drawContents(y, dc, ln.wrap, width, lineStyle, m.RunTimeSettings.WrapMode)
			continue
		}
		if m.RunTimeSettings.WrapMode {
			root.drawContents(y, dc, ln.wrap, width, lineStyle, true)
		} else {
			root.drawContents(y, dc, m.x, width, lineStyle, false)
		}
	}
}

// lineStyle returns the base style for the line.
func (root *Root) lineStyle(m *Document, ln int, isHeader bool) tcell.Style {
	st := m.RunTimeSettings.Style
	style := st.Body
	if isHeader {
		if ln >= root.scr.headerLN && ln < root.scr.headerEnd {
			style = applyStyle(style, st.Header)
		} else {
			// section header
			style = applyStyle(style, st.SectionLine)
		}
		return style
	}
	if m.RunTimeSettings.AlternateRows && ln%2 == 1 {
		style = applyStyle(style, st.Alternate)
	}
	if m.isSectionDelimiter(ln) && m.SectionDelimiterReg != nil {
		style = applyStyle(style, st.SectionLine)
	}
	if m.isMarked(ln) {
		style = applyStyle(style, st.MarkLine)
	}
	if m.jumpTargetNum >= 0 && root.isJumpTargetRow(m, ln) {
		style = applyStyle(style, st.JumpTargetLine)
	}
	return style
}

func (root *Root) isJumpTargetRow(m *Document, ln int) bool {
	return false
}

// fillRow fills the row with the style.
func (root *Root) fillRow(y int, style tcell.Style) {
	for x := 0; x < root.scr.vWidth; x++ {
		root.Screen.SetContent(x, y, ' ', nil, style)
	}
}

// drawEOF draws the EOF marker.
func (root *Root) drawEOF(y int, ln int) {
	x := root.scr.startX
	root.Screen.SetContent(x, y, '~', nil, tcell.StyleDefault.Foreground(tcell.ColorGray))
}

// drawLineNumber draws the line number area.
func (root *Root) drawLineNumber(m *Document, y int, ln lineNumber, isHeader bool) {
	scr := &root.scr
	w := scr.lineNumWidth
	if isHeader {
		for x := 0; x < w+1; x++ {
			root.Screen.SetContent(x, y, ' ', nil, tcell.StyleDefault)
		}
		return
	}
	num := ln.number - m.RunTimeSettings.Header - m.RunTimeSettings.SkipLines + 1
	var s string
	if m.isFilter && ln.number < len(m.lineNumMap) {
		num = m.lineNumMap[ln.number] - m.RunTimeSettings.Header - m.RunTimeSettings.SkipLines + 1
	}
	s = fmt.Sprintf("%*d ", w, num)
	style := m.RunTimeSettings.Style.LineNumber
	x := 0
	for _, r := range s {
		if x >= scr.startX {
			break
		}
		root.Screen.SetContent(x, y, r, nil, style)
		x++
	}
}

// drawContents draws the cells of a line starting at cell offset start.
func (root *Root) drawContents(y int, lc contents, start int, width int, lineStyle tcell.Style, wrap bool) {
	scr := &root.scr
	x := scr.startX
	end := scr.vWidth
	i := start
	if i < 0 {
		i = 0
	}
	for ; i < len(lc) && x < end; i++ {
		c := lc[i]
		if c.width == 0 {
			if c.mainc == cellPlaceholder {
				continue
			}
			continue
		}
		if c.width == 2 {
			if x+2 > end {
				if wrap {
					break
				}
				// draw a blank for the truncated wide char
				root.Screen.SetContent(x, y, ' ', nil, c.style)
				x++
				break
			}
		}
		root.Screen.SetContent(x, y, c.mainc, c.combc, c.style)
		x += c.width
	}
}

// decorateContents applies search highlight, column highlight, multi-color etc.
func (root *Root) decorateContents(m *Document, ln int, lc contents, searcher Searcher, isHeader bool) contents {
	st := m.RunTimeSettings.Style
	lineStyle := root.lineStyle(m, ln, isHeader)
	dc := make(contents, len(lc))
	copy(dc, lc)
	// apply line style as base to each cell (cell styles override)
	if lineStyle != tcell.StyleDefault {
		for i := range dc {
			dc[i].style = mergeStyle(lineStyle, dc[i].style)
		}
	}
	// multi color words
	if len(m.RunTimeSettings.MultiColorWords) > 0 {
		root.applyMultiColor(m, dc)
	}
	// column mode
	if m.RunTimeSettings.ColumnMode && (m.RunTimeSettings.ColumnRainbow || true) {
		root.applyColumnStyles(m, dc, isHeader)
	}
	// search highlight
	if searcher != nil && !isHeader {
		root.applySearchHighlight(dc, searcher, st.SearchHighlight)
	}
	return dc
}

// mergeStyle overlays cell-specific style on the line base style.
func mergeStyle(base tcell.Style, cell tcell.Style) tcell.Style {
	if cell == tcell.StyleDefault {
		return base
	}
	fg, bg, attr := cell.Decompose()
	bfg, bbg, battr := base.Decompose()
	if fg == tcell.ColorDefault {
		fg = bfg
	}
	if bg == tcell.ColorDefault {
		bg = bbg
	}
	attr |= battr
	s := tcell.StyleDefault.Foreground(fg).Background(bg).Attributes(attr)
	// underline style/color
	_, _, uattr := cell.Decompose()
	_ = uattr
	return s
}

// applySearchHighlight highlights matches of the searcher.
func (root *Root) applySearchHighlight(dc contents, searcher Searcher, style tcell.Style) {
	str := dc.String()
	matches := searcher.FindAll(str)
	if len(matches) == 0 {
		return
	}
	rm := contentsRuneMap(dc)
	for _, mt := range matches {
		s, e := mt[0], mt[1]
		if s >= len(rm) {
			continue
		}
		if e >= len(rm) {
			e = len(rm) - 1
		}
		cs, ce := rm[s], rm[e]
		for i := cs; i < ce && i < len(dc); i++ {
			dc[i].style = applyStyle(dc[i].style, style)
		}
	}
}

// applyMultiColor colors configured words.
func (root *Root) applyMultiColor(m *Document, dc contents) {
	styles := m.RunTimeSettings.Style.MultiColorHighlight
	if len(styles) == 0 {
		return
	}
	str := dc.String()
	rm := contentsRuneMap(dc)
	for i, word := range m.RunTimeSettings.MultiColorWords {
		s := NewSearcher(word, root.Config.CaseSensitive, root.Config.SmartCaseSensitive, true)
		if s == nil {
			continue
		}
		style := styles[i%len(styles)]
		for _, mt := range s.FindAll(str) {
			a, b := mt[0], mt[1]
			if a >= len(rm) {
				continue
			}
			if b >= len(rm) {
				b = len(rm) - 1
			}
			for j := rm[a]; j < rm[b] && j < len(dc); j++ {
				dc[j].style = applyStyle(dc[j].style, style)
			}
		}
	}
}

// drawStatus draws the status line.
func (root *Root) drawStatus() {
	scr := &root.scr
	y := scr.statusRow
	m := root.Doc
	// clear
	for x := 0; x < scr.vWidth; x++ {
		root.Screen.SetContent(x, y, ' ', nil, tcell.StyleDefault)
	}
	right := root.positionString(m)
	leftLimit := scr.vWidth - len(right)
	if leftLimit < 0 {
		leftLimit = 0
	}
	if root.input.mode != Normal {
		root.drawInputPrompt(y, leftLimit)
	} else {
		root.drawNormalPrompt(y, leftLimit)
	}
	// right part
	x := scr.vWidth - len(right)
	if x < 0 {
		x = 0
	}
	for _, r := range right {
		if x >= scr.vWidth {
			break
		}
		root.Screen.SetContent(x, y, r, nil, tcell.StyleDefault)
		x++
	}
}

// positionString returns the "(cur/total)" string.
func (root *Root) positionString(m *Document) string {
	if !m.RunTimeSettings.Prompt.ProcessOfCount {
		return ""
	}
	cur := m.topLN + 1
	total := m.BufEndNum()
	if m.BufEOF() {
		return fmt.Sprintf("(%d/%d)", cur, total)
	}
	return fmt.Sprintf("(%d/%d...)", cur, total)
}

// drawNormalPrompt draws the file name and message.
func (root *Root) drawNormalPrompt(y int, limit int) {
	m := root.Doc
	var b strings.Builder
	if m.RunTimeSettings.Prompt.ShowFilename {
		b.WriteString(root.statusName(m))
	}
	b.WriteString(root.message)
	style := tcell.StyleDefault
	if m.RunTimeSettings.Prompt.InvertColor {
		style = style.Reverse(true)
	}
	if root.CurrentDoc > 0 && len(root.DocList) > 1 && m.docType != docHelp && m.docType != docLog {
		style = style.Foreground(tcell.PaletteColor((root.CurrentDoc + 8) % 16))
	}
	x := 0
	for _, r := range b.String() {
		if x >= limit {
			break
		}
		root.Screen.SetContent(x, y, r, nil, style)
		x++
	}
	root.Screen.HideCursor()
}

// drawInputPrompt draws the input prompt and text.
func (root *Root) drawInputPrompt(y int, limit int) {
	in := root.input
	prompt := in.prompt()
	x := 0
	for _, r := range prompt {
		if x >= limit {
			break
		}
		root.Screen.SetContent(x, y, r, nil, tcell.StyleDefault)
		x++
	}
	lc := StrToContents(in.value, -1)
	cursorX := x
	for i, c := range lc {
		if c.width == 0 {
			continue
		}
		if x+c.width > limit {
			break
		}
		if i == in.cursorX {
			cursorX = x
		}
		root.Screen.SetContent(x, y, c.mainc, c.combc, c.style)
		x += c.width
	}
	if in.cursorX >= len(lc) {
		cursorX = x
	}
	root.Screen.ShowCursor(cursorX, y)
}

// drawRuler draws the ruler on the first row.
func (root *Root) drawRuler() {
	scr := &root.scr
	m := root.Doc
	style := m.RunTimeSettings.Style.Ruler
	y := 0
	for x := 0; x < scr.vWidth; x++ {
		root.Screen.SetContent(x, y, ' ', nil, style)
	}
	start := 0
	if m.RunTimeSettings.RulerType == 2 && !m.RunTimeSettings.WrapMode {
		start = m.x
	}
	for x := scr.startX; x < scr.vWidth; x++ {
		n := x - scr.startX + start + 1
		var r rune
		switch {
		case n%10 == 0:
			s := strconv.Itoa(n / 10)
			// write the number ending at this position
			rs := []rune(s)
			for i, rr := range rs {
				px := x - len(rs) + 1 + i
				if px >= scr.startX {
					root.Screen.SetContent(px, y, rr, nil, style)
				}
			}
			continue
		case n%5 == 0:
			r = '+'
		default:
			r = '.'
		}
		root.Screen.SetContent(x, y, r, nil, style)
	}
}
EOF
echo ok"}

