package oviewer

import (
	"strings"

	"github.com/gdamore/tcell/v2"
)

// InputMode is the type of input mode.
type InputMode int

// Input modes.
const (
	Normal InputMode = iota
	ViewMode
	Search
	Backsearch
	Filter
	Goline
	Header
	Delimiter
	TabWidth
	Watch
	SkipLines
	MultiColor
	JumpTarget
	SaveBuffer
	SectionDelimiter
	SectionStart
	SectionNum
	ConvertType
	VerticalHeader
	HeaderColumn
	MarkNumber
	MarkByPattern
)

// Input holds the state of the input line.
type Input struct {
	mode    InputMode
	value   string
	cursorX int // rune index of cursor
	// candidates per mode
	candidates map[InputMode]*candidate
	// search options shown in the prompt
	// (owned by Root but mirrored here for drawing)
	caseSensitive      bool
	smartCaseSensitive bool
	regexpSearch       bool
	incsearch          bool
	nonMatch           bool
}

type candidate struct {
	list []string
	p    int
}

// NewInput returns an Input.
func NewInput() *Input {
	in := &Input{candidates: map[InputMode]*candidate{}}
	in.candidates[ViewMode] = &candidate{}
	in.candidates[ConvertType] = &candidate{list: []string{ConvEscaped, ConvRaw, ConvAlign}}
	in.candidates[Delimiter] = &candidate{list: []string{",", "|", "\t"}}
	in.candidates[TabWidth] = &candidate{list: []string{"3", "2", "4", "8"}}
	in.candidates[Watch] = &candidate{list: []string{"3", "2", "1"}}
	in.candidates[SectionDelimiter] = &candidate{list: []string{"^commit", "^diff", "^#", "^$", "^\\f"}}
	in.candidates[JumpTarget] = &candidate{list: []string{"section"}}
	return in
}

// prompt returns the prompt string for the current mode.
func (in *Input) prompt() string {
	switch in.mode {
	case Search:
		return in.searchOptions(false) + "/"
	case Backsearch:
		return in.searchOptions(false) + "?"
	case Filter:
		p := ""
		if in.nonMatch {
			p = "Non-match"
		}
		return p + in.searchOptions(true) + "&"
	case MarkByPattern:
		return in.searchOptions(true) + "*"
	case Goline:
		return "Goto line:"
	case Header:
		return "Header length:"
	case Delimiter:
		return "Delimiter:"
	case TabWidth:
		return "TAB width:"
	case Watch:
		return "Watch interval:"
	case SkipLines:
		return "Skip lines:"
	case MultiColor:
		return "Multi color:"
	case JumpTarget:
		return "Jump target line:"
	case SaveBuffer:
		return "(Save)file:"
	case SectionDelimiter:
		return "Section delimiter:"
	case SectionStart:
		return "Section start:"
	case SectionNum:
		return "Section Num:"
	case ConvertType:
		return "Convert:"
	case VerticalHeader:
		return "Vertical header length:"
	case HeaderColumn:
		return "Header column:"
	case ViewMode:
		return "Mode:"
	case MarkNumber:
		return "Mark number:"
	}
	return ""
}

// searchOptions returns the "(R)(I)(Aa)" prefix.
func (in *Input) searchOptions(noInc bool) string {
	var b strings.Builder
	if in.regexpSearch {
		b.WriteString("(R)")
	}
	if in.incsearch && !noInc {
		b.WriteString("(I)")
	}
	if in.caseSensitive {
		b.WriteString("(Aa)")
	} else if in.smartCaseSensitive {
		b.WriteString("(S)")
	}
	return b.String()
}

// isSearchMode reports whether the mode is one of the search modes.
func (in *Input) isSearchMode() bool {
	switch in.mode {
	case Search, Backsearch, Filter, MarkByPattern:
		return true
	}
	return false
}

// reset clears the input.
func (in *Input) reset() {
	in.mode = Normal
	in.value = ""
	in.cursorX = 0
}

// start begins a new input mode.
func (in *Input) start(mode InputMode) {
	in.mode = mode
	in.value = ""
	in.cursorX = 0
	if c, ok := in.candidates[mode]; ok {
		c.p = len(c.list)
	}
}

// insert inserts the string at the cursor.
func (in *Input) insert(s string) {
	r := []rune(in.value)
	if in.cursorX > len(r) {
		in.cursorX = len(r)
	}
	ins := []rune(s)
	nr := make([]rune, 0, len(r)+len(ins))
	nr = append(nr, r[:in.cursorX]...)
	nr = append(nr, ins...)
	nr = append(nr, r[in.cursorX:]...)
	in.value = string(nr)
	in.cursorX += len(ins)
}

// backspace deletes the rune before the cursor.
func (in *Input) backspace() {
	r := []rune(in.value)
	if in.cursorX <= 0 || in.cursorX > len(r) {
		return
	}
	nr := append([]rune{}, r[:in.cursorX-1]...)
	nr = append(nr, r[in.cursorX:]...)
	in.value = string(nr)
	in.cursorX--
}

// delete deletes the rune at the cursor.
func (in *Input) delete() {
	r := []rune(in.value)
	if in.cursorX < 0 || in.cursorX >= len(r) {
		return
	}
	nr := append([]rune{}, r[:in.cursorX]...)
	nr = append(nr, r[in.cursorX+1:]...)
	in.value = string(nr)
}

// addCandidate records the value in the history of the mode.
func (in *Input) addCandidate(mode InputMode, v string) {
	if v == "" {
		return
	}
	c, ok := in.candidates[mode]
	if !ok {
		c = &candidate{}
		in.candidates[mode] = c
	}
	// remove duplicates
	for i, s := range c.list {
		if s == v {
			c.list = append(c.list[:i], c.list[i+1:]...)
			break
		}
	}
	c.list = append(c.list, v)
	c.p = len(c.list)
}

// previousCandidate moves to the previous history entry.
func (in *Input) previousCandidate() {
	c, ok := in.candidates[in.mode]
	if !ok || len(c.list) == 0 {
		return
	}
	if c.p > 0 {
		c.p--
	}
	in.value = c.list[c.p]
	in.cursorX = len([]rune(in.value))
}

// nextCandidate moves to the next history entry.
func (in *Input) nextCandidate() {
	c, ok := in.candidates[in.mode]
	if !ok || len(c.list) == 0 {
		return
	}
	if c.p < len(c.list)-1 {
		c.p++
		in.value = c.list[c.p]
	} else {
		c.p = len(c.list)
		in.value = ""
	}
	in.cursorX = len([]rune(in.value))
}

// inputKeyEvent handles key events while in an input mode.
func (root *Root) inputKeyEvent(ev *tcell.EventKey) {
	in := root.input
	ke := keyEventFromTcell(ev)
	// input specific bindings
	if action, ok := root.inputMap[ke]; ok {
		if root.inputAction(action) {
			return
		}
	}
	// cancel keys
	for _, name := range root.cancelKeys {
		if k, err := parseKeyName(name); err == nil && k == ke {
			root.inputCancel()
			return
		}
	}
	switch ev.Key() {
	case tcell.KeyEscape:
		root.inputCancel()
		return
	case tcell.KeyEnter:
		root.inputConfirm()
		return
	case tcell.KeyBackspace, tcell.KeyBackspace2:
		in.backspace()
	case tcell.KeyDelete:
		in.delete()
