{"command":"cd /workspace/oviewer && cat > move.go <<'EOF'
package oviewer

import (
	"strconv"
	"strings"
)

// startLN returns the first line number of the body.
func (m *Document) startLN() int {
	return m.RunTimeSettings.SkipLines + m.RunTimeSettings.Header
}

// bodyWidthFor returns the width available for contents.
func (root *Root) bodyWidthFor(m *Document) int {
	return root.scr.bodyWidth()
}

// bottomPosition returns the top position (ln, lx) at which the EOF marker is
// displayed on the last body row.
func (root *Root) bottomPosition(m *Document) (int, int) {
	rows := root.scr.bodyRows()
	width := root.bodyWidthFor(m)
	endNum := m.BufEndNum()
	// rows above the EOF marker.
	remain := rows - 1
	ln := endNum
	lx := 0
	if remain <= 0 {
		return endNum, 0
	}
	if !m.RunTimeSettings.WrapMode {
		return endNum - remain, 0
	}
	for remain > 0 {
		ln--
		if ln < 0 {
			remain--
			continue
		}
		lc := m.getContents(ln)
		starts := wrapStarts(lc, width)
		if len(starts) <= remain {
			remain -= len(starts)
			lx = 0
			continue
		}
		// partial: take the last `remain` wraps
		lx = starts[len(starts)-remain]
		remain = 0
	}
	return ln, lx
}

// isAtBottom reports whether the position is at or beyond the bottom.
func (root *Root) isAtBottom(m *Document) bool {
	bln, blx := root.bottomPosition(m)
	if m.topLN > bln {
		return true
	}
	if m.topLN == bln && m.topLX >= blx {
		return true
	}
	return false
}

// clampBottom moves the position back to the bottom if beyond it.
func (root *Root) clampBottom(m *Document) {
	bln, blx := root.bottomPosition(m)
	if m.topLN > bln || (m.topLN == bln && m.topLX > blx) {
		m.topLN = bln
		m.topLX = blx
	}
}

// moveTop moves to the top of the document.
func (root *Root) moveTop() {
	m := root.Doc
	m.topLN = m.startLN()
	m.topLX = 0
}

// moveBottom moves to the bottom of the document.
func (root *Root) moveBottom() {
	root.moveBottomDoc(root.Doc)
}

// moveBottomDoc moves the document to the bottom.
func (root *Root) moveBottomDoc(m *Document) {
	if m != root.Doc {
		// compute with the layout of that document (approximation: same size)
		saved := root.Doc
		root.Doc = m
		root.prepareScreen()
		ln, lx := root.bottomPosition(m)
		m.topLN, m.topLX = ln, lx
		root.Doc = saved
		root.prepareScreen()
		return
	}
	root.prepareScreen()
	ln, lx := root.bottomPosition(m)
	m.topLN, m.topLX = ln, lx
}

// moveDownRows moves down n screen rows.
func (root *Root) moveDownRows(n int) {
	m := root.Doc
	root.prepareScreen()
	if root.isAtBottom(m) {
		return
	}
	width := root.bodyWidthFor(m)
	endNum := m.BufEndNum()
	for i := 0; i < n; i++ {
		if m.topLN < 0 {
			m.topLN++
			m.topLX = 0
			continue
		}
		if !m.RunTimeSettings.WrapMode || m.topLN >= endNum {
			m.topLN++
			m.topLX = 0
			continue
		}
		lc := m.getContents(m.topLN)
		next := nextWrap(lc, width, m.topLX)
		if next >= 0 {
			m.topLX = next
		} else {
			m.topLN++
			m.topLX = 0
		}
	}
	root.clampBottom(m)
}

// moveUpRows moves up n screen rows.
func (root *Root) moveUpRows(n int) {
	m := root.Doc
	root.prepareScreen()
	width := root.bodyWidthFor(m)
	start := m.startLN()
	if m.topLN < start || (m.topLN == start && m.topLX == 0) {
		m.topLN = start
		m.topLX = 0
		return
	}
	for i := 0; i < n; i++ {
		if m.topLN <= start && m.topLX == 0 {
			break
		}
		if !m.RunTimeSettings.WrapMode {
			m.topLN--
			m.topLX = 0
			continue
		}
		if m.topLX > 0 {
			lc := m.getContents(m.topLN)
			m.topLX = prevWrap(lc, width, m.topLX)
			if m.topLX < 0 {
				m.topLX = 0
			}
			continue
		}
		m.topLN--
		lc := m.getContents(m.topLN)
		m.topLX = lastWrap(lc, width)
	}
	if m.topLN < start {
		m.topLN = start
		m.topLX = 0
	}
}

// moveDown moves down one line (row).
func (root *Root) moveDown() {
	root.moveDownRows(root.vScrollLines())
}

// moveUp moves up one line (row).
func (root *Root) moveUp() {
	root.moveUpRows(root.vScrollLines())
}

func (root *Root) vScrollLines() int {
	n := root.Doc.RunTimeSettings.VScrollLines
	if n <= 0 {
		return 1
	}
	return n
}

// movePgDn moves down one page.
func (root *Root) movePgDn() {
	root.prepareScreen()
	root.moveDownRows(root.scr.bodyRows())
}

// movePgUp moves up one page.
func (root *Root) movePgUp() {
	root.prepareScreen()
	root.moveUpRows(root.scr.bodyRows())
}

// moveHfDn moves down half a page.
func (root *Root) moveHfDn() {
	root.prepareScreen()
	root.moveDownRows(root.scr.bodyRows() / 2)
}

// moveHfUp moves up half a page.
func (root *Root) moveHfUp() {
	root.prepareScreen()
	root.moveUpRows(root.scr.bodyRows() / 2)
}

// moveLines moves to make the line the top (used by search, goto).
func (root *Root) moveLine(ln int) {
	m := root.Doc
	start := m.startLN()
	if ln < start {
		ln = start
	}
	m.topLN = ln
	m.topLX = 0
}

// Horizontal movement.

// hScrollWidth returns the number of cells for width_left/right.
func (root *Root) hScrollWidth(m *Document) int {
	w := root.scr.bodyWidth()
	s := m.RunTimeSettings.HScrollWidth
	n := parseWidthSpec(s, w)
	if n <= 0 {
		n = 1
	}
	return n
}

// parseWidthSpec parses "10", "10%", ".1" relative to width.
func parseWidthSpec(s string, width int) int {
	s = strings.TrimSpace(s)
	if s == "" {
		return 0
	}
	if strings.HasSuffix(s, "%") {
		p, err := strconv.ParseFloat(strings.TrimSuffix(s, "%"), 64)
		if err != nil {
			return 0
		}
		return int(float64(width) * p / 100)
	}
	if strings.HasPrefix(s, ".") {
		p, err := strconv.ParseFloat(s, 64)
		if err != nil {
			return 0
		}
		return int(float64(width) * p)
	}
	n, err := strconv.Atoi(s)
	if err != nil {
		return 0
	}
	return n
}

// maxVisibleWidth returns the maximum content width of the lines on screen.
func (root *Root) maxVisibleWidth(m *Document) int {
	max := 0
	for _, r := range root.scr.rows {
		if !r.valid {
			continue
		}
		lc := m.getContents(r.number)
		if len(lc) > max {
			max = len(lc)
		}
	}
	return max
}

// rightLimit returns the maximum x offset.
func (root *Root) rightLimit(m *Document) int {
	limit := root.maxVisibleWidth(m) - root.scr.bodyWidth() + 2
	if limit < 0 {
		limit = 0
	}
	return limit
}

// moveLeft scrolls left by n cells.
func (root *Root) moveLeft(n int) {
	m := root.Doc
	if m.RunTimeSettings.WrapMode {
		return
	}
	if m.RunTimeSettings.ColumnMode {
		root.columnLeft(n)
		return
	}
	m.x -= n
	if m.x < 0 {
		m.x = 0
	}
}

// moveRight scrolls right by n cells.
func (root *Root) moveRight(n int) {
	m := root.Doc
	if m.RunTimeSettings.WrapMode {
		return
	}
	if m.RunTimeSettings.ColumnMode {
		root.columnRight(n)
		return
	}
	root.prepareScreen()
	limit := root.rightLimit(m)
	m.x += n
	if m.x > limit {
		m.x = limit
	}
	if m.x < 0 {
		m.x = 0
	}
}

// moveBeginLeft moves to the beginning of the line.
func (root *Root) moveBeginLeft() {
	m := root.Doc
	m.x = 0
	if m.RunTimeSettings.ColumnMode {
		m.columnCursor = 0
	}
}

// moveEndRight moves to the end of the longest visible line.
func (root *Root) moveEndRight() {
	m := root.Doc
	if m.RunTimeSettings.WrapMode {
		return
	}
	root.prepareScreen()
	if m.RunTimeSettings.ColumnMode {
		root.columnEnd()
		return
	}
	m.x = root.rightLimit(m)
}

// moveHfLeft scrolls left half a screen.
func (root *Root) moveHfLeft() {
	root.prepareScreen()
	root.moveLeft(root.scr.bodyWidth() / 2)
}

// moveHfRight scrolls right half a screen.
func (root *Root) moveHfRight() {
	root.prepareScreen()
	root.moveRight(root.scr.bodyWidth() / 2)
}

// moveWidthLeft scrolls left by the configured width.
func (root *Root) moveWidthLeft() {
	root.prepareScreen()
	root.moveLeft(root.hScrollWidth(root.Doc))
}

// moveWidthRight scrolls right by the configured width.
func (root *Root) moveWidthRight() {
	root.prepareScreen()
	root.moveRight(root.hScrollWidth(root.Doc))
}
