	col := m.columnCursor
	m.shrinkCols[col] = !m.shrinkCols[col]
	m.clearCache()
	root.setMessagef("Set shrink column %d %t", col, m.shrinkCols[col])
}

func (root *Root) toggleRightAlign() {
	m := root.Doc
	if m.RunTimeSettings.Converter != ConvAlign {
		root.setMessage("Not in align mode")
		return
	}
	col := m.columnCursor
	m.rightAlign[col] = !m.rightAlign[col]
	m.clearCache()
	root.setMessagef("Set right align column %d %t", col, m.rightAlign[col])
}

func (root *Root) toggleHideOtherSection() {
	m := root.Doc
	m.RunTimeSettings.HideOtherSection = !m.RunTimeSettings.HideOtherSection
	root.setMessagef("Set HideOtherSection %t", m.RunTimeSettings.HideOtherSection)
}

func (root *Root) toggleWriteOriginal() {
	root.IsWriteOriginal = !root.IsWriteOriginal
	root.setMessagef("Set WriteOriginal %t", root.IsWriteOriginal)
}

func (root *Root) toggleMouse() {
	root.mouseEnabled = !root.mouseEnabled
	if root.mouseEnabled {
		root.Screen.EnableMouse()
		root.setMessage("Enable Mouse")
	} else {
		root.Screen.DisableMouse()
		root.setMessage("Disable Mouse")
	}
}

func (root *Root) toggleFollowMode() {
	m := root.Doc
	m.FollowMode = !m.FollowMode
	if m.FollowMode {
		m.latestNum = -1
	}
	root.setMessagef("Set Follow Mode %t", m.FollowMode)
}

func (root *Root) toggleFollowAll() {
	root.followAll = !root.followAll
	root.setMessagef("Set Follow All %t", root.followAll)
}

func (root *Root) toggleFollowSection() {
	m := root.Doc
	m.FollowSection = !m.FollowSection
	root.setMessagef("Set Follow Section %t", m.FollowSection)
}

func (root *Root) alignFormat() {
	m := root.Doc
	if m.RunTimeSettings.Converter == ConvAlign {
		root.setConverter(ConvEscaped)
		return
	}
	root.setConverter(ConvAlign)
}

func (root *Root) rawFormat() {
	m := root.Doc
	if m.RunTimeSettings.Converter == ConvRaw {
		root.setConverter(ConvEscaped)
		return
	}
	root.setConverter(ConvRaw)
}

// setConverter sets the converter type.
func (root *Root) setConverter(name string) {
	m := root.Doc
	switch name {
	case ConvEscaped:
		m.RunTimeSettings.Converter = ConvEscaped
		root.setMessage("Set es converter")
	case ConvRaw:
		m.RunTimeSettings.Converter = ConvRaw
		root.setMessage("Set raw converter")
	case ConvAlign:
		m.RunTimeSettings.Converter = ConvAlign
		root.setMessage("Set align converter")
	default:
		root.setMessagef("Unknown converter %s", name)
		return
	}
	m.clearCache()
}

// Input setters.

func (root *Root) goLine(input string) {
	m := root.Doc
	input = strings.TrimSpace(input)
	if input == "" {
		return
	}
	var ln int
	num := m.BufEndNum()
	switch {
	case strings.HasSuffix(input, "%"):
		p, err := strconv.ParseFloat(strings.TrimSuffix(input, "%"), 64)
		if err != nil {
			root.setMessagef("Invalid number: %s", input)
			return
		}
		ln = int(float64(num) * p / 100)
	case strings.HasPrefix(input, "."):
		p, err := strconv.ParseFloat(input, 64)
		if err != nil {
			root.setMessagef("Invalid number: %s", input)
			return
		}
		ln = int(float64(num) * p)
	default:
		n, err := strconv.Atoi(input)
		if err != nil {
			root.setMessagef("Invalid number: %s", input)
			return
		}
		ln = n
	}
	root.goLineNumber(ln)
}

// goLineNumber moves to the 1-based line number.
func (root *Root) goLineNumber(ln int) {
	m := root.Doc
	ln = ln - 1 - m.RunTimeSettings.Header
	root.moveLine(ln)
	root.setMessagef("Moved to line %d", ln+1+m.RunTimeSettings.Header)
}

func (root *Root) setHeader(input string) {
	m := root.Doc
	n, err := strconv.Atoi(strings.TrimSpace(input))
	if err != nil || n < 0 {
		root.setMessagef("Invalid number: %s", input)
		return
	}
	if n > root.scr.vHeight-1 {
		root.setMessagef("Header must be less than %d", root.scr.vHeight-1)
		return
	}
	if m.RunTimeSettings.Header == n {
		return
	}
	m.RunTimeSettings.Header = n
	m.clearCache()
	root.setMessagef("Set Header %d", n)
}

func (root *Root) setSkipLines(input string) {
	m := root.Doc
	n, err := strconv.Atoi(strings.TrimSpace(input))
	if err != nil || n < 0 {
		root.setMessagef("Invalid number: %s", input)
		return
	}
	if m.RunTimeSettings.SkipLines == n {
		return
	}
	m.RunTimeSettings.SkipLines = n
	root.setMessagef("Set SkipLines %d", n)
}

func (root *Root) setTabWidth(input string) {
	m := root.Doc
	n, err := strconv.Atoi(strings.TrimSpace(input))
	if err != nil {
		root.setMessagef("Invalid number: %s", input)
		return
	}
	if m.RunTimeSettings.TabWidth == n {
		return
	}
	m.RunTimeSettings.TabWidth = n
	m.clearCache()
	root.setMessagef("Set tab width %d", n)
}

func (root *Root) setDelimiter(input string) {
	m := root.Doc
	m.setDelimiter(input)
	m.clearCache()
	root.setMessagef("Set delimiter %s", input)
}

func (root *Root) setWatchInterval(input string) {
	m := root.Doc
	n, err := strconv.Atoi(strings.TrimSpace(input))
	if err != nil {
		root.setMessagef("Invalid number: %s", input)
		return
	}
	m.watchInterval = n
	if n <= 0 {
		root.unWatchMode()
		return
	}
	root.watchMode(n)
	root.setMessagef("Set watch interval %d", n)
}

func (root *Root) setMultiColor(input string) {
	m := root.Doc
	words := strings.Split(input, " ")
	var list []string
	for _, w := range words {
		if w != "" {
			list = append(list, w)
		}
	}
	m.RunTimeSettings.MultiColorWords = list
	root.setMessagef("Set multi color %s", input)
}

func (root *Root) setJumpTarget(input string) {
	m := root.Doc
	m.setJumpTarget(input)
	root.setMessagef("Set JumpTarget %s", input)
}

// setJumpTarget resolves the jump target specification.
func (m *Document) setJumpTarget(input string) {
	m.RunTimeSettings.JumpTarget = input
	m.jumpTargetNum = -1
	m.jumpTargetSection = false
	input = strings.TrimSpace(input)
	if input == "" {
		return
	}
	if input == "section" {
		m.jumpTargetSection = true
		return
	}
	m.jumpTargetNum = 0
	m.jumpTargetSpec = input
}

func (root *Root) setSectionDelimiter(input string) {
	m := root.Doc
	if input != "" {
		if _, err := regexp.Compile(input); err != nil {
			root.setMessagef("Invalid regexp: %s", input)
			return
		}
	}
	m.setSectionDelimiter(input)
	root.setMessagef("Set section delimiter %s", input)
}

func (root *Root) setSectionStart(input string) {
	m := root.Doc
	n, err := strconv.Atoi(strings.TrimSpace(input))
	if err != nil {
		root.setMessagef("Invalid number: %s", input)
		return
	}
	m.RunTimeSettings.SectionStartPosition = n
	root.setMessagef("Set section start position %d", n)
}

func (root *Root) setSectionNum(input string) {
	m := root.Doc
	n, err := strconv.Atoi(strings.TrimSpace(input))
	if err != nil || n < 0 {
		root.setMessagef("Invalid number: %s", input)
		return
	}
	m.RunTimeSettings.SectionHeaderNum = n
	root.setMessagef("Set section header num %d", n)
}

func (root *Root) setVerticalHeader(input string) {
	m := root.Doc
	n, err := strconv.Atoi(strings.TrimSpace(input))
	if err != nil || n < 0 {
		root.setMessagef("Invalid number: %s", input)
		return
	}
	m.RunTimeSettings.VerticalHeader = n
	m.RunTimeSettings.HeaderColumn = 0
	root.setMessagef("Set vertical header %d", n)
}

func (root *Root) setHeaderColumn(input string) {
	m := root.Doc
	n, err := strconv.Atoi(strings.TrimSpace(input))
	if err != nil || n < 0 {
		root.setMessagef("Invalid number: %s", input)
		return
	}
	m.RunTimeSettings.HeaderColumn = n
	m.RunTimeSettings.VerticalHeader = 0
	root.setMessagef("Set header column %d", n)
}

func (root *Root) setViewMode(input string) {
	input = strings.TrimSpace(input)
	m := root.Doc
	if input == "general" || input == "" {
		s := settingsFromConfigNoMode(root.Config)
		root.applySettingsKeepStyle(m, s)
		root.setMessagef("Set mode %s", "general")
		return
	}
	mode, ok := root.Config.Mode[input]
	if !ok {
		root.setMessagef("Invalid mode %s", input)
		return
	}
	s := settingsFromConfigNoMode(root.Config)
	applyRunTime(&s, mode)
	root.applySettingsKeepStyle(m, s)
	root.setMessagef("Set mode %s", input)
}

// settingsFromConfigNoMode returns the general settings without applying ViewMode.
func settingsFromConfigNoMode(cfg Config) DocSettings {
	c := cfg
	c.ViewMode = ""
	return settingsFromConfig(c)
}

// applySettingsKeepStyle applies new settings to the document.
func (root *Root) applySettingsKeepStyle(m *Document, s DocSettings) {
	m.RunTimeSettings = s
	m.setDelimiter(s.ColumnDelimiter)
	m.setSectionDelimiter(s.SectionDelimiter)
	m.setJumpTarget(s.JumpTarget)
	m.clearCache()
}

// Marks.

func (root *Root) addMark() {
	m := root.Doc
	ln := m.topLN
	m.addMark(ln)
	root.setMessagef("Marked to line %d", ln-m.RunTimeSettings.Header+1)
}

func (root *Root) removeMark() {
	m := root.Doc
	ln := m.topLN
	if !m.removeMark(ln) {
		root.setMessagef("Not marked line %d", ln-m.RunTimeSettings.Header+1)
		return
	}
	root.setMessagef("Remove the mark at line %d", ln-m.RunTimeSettings.Header+1)
}

func (root *Root) removeAllMark() {
	m := root.Doc
	m.marked = nil
	m.markedPoint = 0
	root.setMessage("Remove all marks")
}

func (root *Root) nextMark() {
	m := root.Doc
	if len(m.marked) == 0 {
		return
	}
	if m.markedPoint < len(m.marked)-1 {
		m.markedPoint++
	} else {
		m.markedPoint = 0
	}
	root.goMark(m.markedPoint)
}

func (root *Root) prevMark() {
	m := root.Doc
	if len(m.marked) == 0 {
		return
	}
	if m.markedPoint > 0 {
		m.markedPoint--
	} else {
		m.markedPoint = len(m.marked) - 1
	}
	root.goMark(m.markedPoint)
}

func (root *Root) goMark(i int) {
	m := root.Doc
	if i < 0 || i >= len(m.marked) {
		return
	}
	root.moveLine(m.marked[i])
	root.setMessagef("Moved to mark %d", i+1)
}

func (root *Root) goMarkNumber(input string) {
	n, err := strconv.Atoi(strings.TrimSpace(input))
	if err != nil {
		root.setMessagef("Invalid number: %s", input)
		return
	}
	m := root.Doc
	if n < 1 || n > len(m.marked) {
		root.setMessagef("Mark number %d not found", n)
		return
	}
	m.markedPoint = n - 1
	root.goMark(n - 1)
}

func (root *Root) markByPattern(input string) {
	m := root.Doc
	s := root.newSearcher(input)
	if s == nil {
		return
	}
	count := 0
	for i := 0; i < m.BufEndNum(); i++ {
		if s.Match(stripEscape(m.GetLine(i))) {
			m.addMark(i)
			count++
		}
	}
	root.setMessagef("Marked %d lines", count)
}

// Documents.

func (root *Root) nextDoc() {
	root.setDocument(root.CurrentDoc + 1)
}

func (root *Root) previousDoc() {
	root.setDocument(root.CurrentDoc - 1)
}

// setDocument switches to the document number.
func (root *Root) setDocument(n int) {
	root.mu.Lock()
	defer root.mu.Unlock()
	if n < 0 || n >= len(root.DocList) {
		return
	}
	if root.Doc.docType == docHelp || root.Doc.docType == docLog {
		root.Doc = root.DocList[n]
		root.CurrentDoc = n
		root.input.reset()
		root.message = ""
		return
	}
	prev := root.Doc
	root.CurrentDoc = n
	root.Doc = root.DocList[n]
	root.syncFilterPosition(prev, root.Doc)
	root.input.reset()
	root.message = ""
	if root.Config.SetTerminalTitle {
		root.setTitle()
	}
}

// syncFilterPosition synchronizes the position between a filter document
// and its parent.
func (root *Root) syncFilterPosition(from, to *Document) {
	if from.isFilter && from.parent == to {
		// filter -> parent
		if from.topLN >= 0 && from.topLN < len(from.lineNumMap) {
			to.topLN = from.lineNumMap[from.topLN]
			to.topLX = 0
		}
		return
	}
	if to.isFilter && to.parent == from {
		// parent -> filter: find the first filtered line >= parent top
		for i, ln := range to.lineNumMap {
			if ln >= from.topLN {
				to.topLN = i
				to.topLX = 0
				return
			}
		}
	}
}

// closeDocument closes the current document.
func (root *Root) closeDocument() {
	root.mu.Lock()
	defer root.mu.Unlock()
	if root.Doc.docType == docHelp || root.Doc.docType == docLog {
		return
	}
	if len(root.DocList) <= 1 {
		root.setMessage("only this document")
		return
	}
	n := root.CurrentDoc
	m := root.DocList[n]
	m.close()
	root.DocList = append(root.DocList[:n], root.DocList[n+1:]...)
	if n >= len(root.DocList) {
		n = len(root.DocList) - 1
	}
	root.CurrentDoc = n
	root.Doc = root.DocList[n]
	root.setMessagef("close [%d]%s", root.CurrentDoc, root.Doc.visibleName())
}

// closeAllFilter closes all filter documents.
func (root *Root) closeAllFilter() {
	root.mu.Lock()
	defer root.mu.Unlock()
	var names []string
	var list []*Document
	for _, m := range root.DocList {
		if m.isFilter {
			names = append([]string{m.visibleName()}, names...)
			m.close()
			continue
		}
		list = append(list, m)
	}
	if len(names) == 0 {
		root.setMessage("no filter document")
		return
	}
	root.DocList = list
	if root.Doc.isFilter || root.CurrentDoc >= len(list) {
		root.CurrentDoc = len(list) - 1
		// prefer the parent of the filter
		for i, m := range list {
			if m == root.Doc.parent {
				root.CurrentDoc = i
			}
		}
		root.Doc = list[root.CurrentDoc]
	} else {
		for i, m := range list {
			if m == root.Doc {
				root.CurrentDoc = i
			}
		}
	}
	root.setMessagef("close %s", strings.Join(names, ", "))
}

// closeFile closes the file of the current document (stops reading).
func (root *Root) closeFile() {
	m := root.Doc
	if m.preventReload {
		root.setMessage("cannot close")
		return
	}
	if err := m.close(); err != nil {
		root.setMessageLogf("close: %s", err)
		return
	}
	root.setMessageLogf("close file %s", m.FileName)
}

// reload reloads the current document.
func (root *Root) reload() {
	m := root.Doc
	if m.preventReload {
		root.setMessage("cannot reload")
		return
	}
	if err := root.reloadDoc(m); err != nil {
		root.setMessageLogf("reload: %s", err)
		return
	}
	root.setMessageLogf("reload file %s", m.FileName)
}

// reloadDoc re-reads the document from its file.
func (root *Root) reloadDoc(m *Document) error {
	if m.reloadFunc == nil {
		return ErrPreventReload
	}
	m.reset()
	m.topLN = m.startLN()
	m.topLX = 0
	return m.reloadFunc()
}

// Watch.

func (root *Root) toggleWatch() {
	m := root.Doc
	if m.WatchMode {
		root.unWatchMode()
		return
	}
	interval := m.watchInterval
	if interval <= 0 {
		interval = 1
	}
	root.watchMode(interval)
}

func (root *Root) watchMode(interval int) {
	m := root.Doc
	m.WatchMode = true
	m.watchInterval = interval
	m.FollowSection = true
	root.setMessagef("Set watch mode %d", interval)
	root.startWatch(m, interval)
}

func (root *Root) unWatchMode() {
	m := root.Doc
	m.WatchMode = false
	m.FollowSection = false
	root.setMessage("Unset watch mode")
}

// viewSync redraws the screen.
func (root *Root) viewSync() {
	root.Doc.clearCache()
	root.Screen.Sync()
}

// suspend suspends the process (SIGSTOP).
func (root *Root) suspend() {
	root.Screen.Suspend()
	fmt.Fprintln(os.Stderr, "suspended ov")
	pid := syscall.Getpid()
	if err := syscall.Kill(pid, syscall.SIGSTOP); err != nil {
		root.setMessageLogf("suspend: %s", err)
	}
	// resumed
	root.Screen.Resume()
	root.Screen.Sync()
}

// edit opens the current document in $EDITOR.
func (root *Root) edit() {
	m := root.Doc
	editor := os.Getenv("EDITOR")
	if editor == "" {
		editor = "vi"
	}
	if m.FileName == "" || m.preventReload {
		root.setMessage("cannot edit")
		return
	}
	root.Screen.Suspend()
	cmd := exec.Command(editor, m.FileName)
	cmd.Stdin = os.Stdin
	cmd.Stdout = os.Stdout
	cmd.Stderr = os.Stderr
	err := cmd.Run()
	root.Screen.Resume()
	root.Screen.Sync()
	if err != nil {
		root.setMessageLogf("edit: %s", err)
		return
	}
	root.reloadDoc(m)
}

// saveBuffer writes the document to a file.
func (root *Root) saveBuffer(name string) {
	name = strings.TrimSpace(name)
	if name == "" {
		return
	}
	m := root.Doc
	f, err := os.OpenFile(name, os.O_WRONLY|os.O_CREATE|os.O_EXCL, 0o644)
	if err != nil {
		root.setMessageLogf("save: %s", err)
		return
	}
	defer f.Close()
	for i := 0; i < m.BufEndNum(); i++ {
		fmt.Fprintln(f, m.GetLine(i))
	}
	root.setMessageLogf("saved %s", name)
}
EOF
echo ok"}

