package oviewer

import (
	"strings"

	"github.com/gdamore/tcell/v2"
)

// columnRanges returns the [start,end) cell ranges of the columns of the line.
func (m *Document) columnRanges(lc contents) [][2]int {
	str := lc.String()
	rm := contentsRuneMap(lc)
	delm := m.RunTimeSettings.ColumnDelimiter
	var ranges [][2]int
	if m.RunTimeSettings.ColumnDelimiterReg != nil {
		locs := m.RunTimeSettings.ColumnDelimiterReg.FindAllStringIndex(str, -1)
		prev := 0
		for _, l := range locs {
			ranges = append(ranges, [2]int{byteToRune(str, prev), byteToRune(str, l[0])})
			prev = l[1]
		}
		ranges = append(ranges, [2]int{byteToRune(str, prev), byteToRune(str, len(str))})
	} else {
		if delm == "" {
			return nil
		}
		parts := strings.Split(str, delm)
		pos := 0
		dl := len([]rune(delm))
		for _, p := range parts {
			n := len([]rune(p))
			ranges = append(ranges, [2]int{pos, pos + n})
			pos += n + dl
		}
	}
	// convert rune positions to cell positions
	res := make([][2]int, 0, len(ranges))
	for _, r := range ranges {
		s, e := r[0], r[1]
		if s >= len(rm) {
			s = len(rm) - 1
		}
		if e >= len(rm) {
			e = len(rm) - 1
		}
		res = append(res, [2]int{rm[s], rm[e]})
	}
	return res
}

// applyColumnStyles applies rainbow and column highlight.
func (root *Root) applyColumnStyles(m *Document, dc contents, isHeader bool) {
	ranges := m.columnRanges(dc)
	if len(ranges) == 0 {
		return
	}
	st := m.RunTimeSettings.Style
	if m.RunTimeSettings.ColumnRainbow && len(st.ColumnRainbow) > 0 {
		for i, r := range ranges {
			style := st.ColumnRainbow[i%len(st.ColumnRainbow)]
			for j := r[0]; j < r[1] && j < len(dc); j++ {
				dc[j].style = applyStyle(dc[j].style, style)
			}
		}
	}
	cur := m.columnCursor
	if cur >= 0 && cur < len(ranges) {
		r := ranges[cur]
		for j := r[0]; j < r[1] && j < len(dc); j++ {
			dc[j].style = applyStyle(dc[j].style, st.ColumnHighlight)
		}
	}
}

// columnCount returns the number of columns on the visible lines.
func (root *Root) columnCount(m *Document) int {
	max := 0
	for _, r := range root.scr.rows {
		if !r.valid {
			continue
		}
		n := len(m.columnRanges(m.getContents(r.number)))
		if n > max {
			max = n
		}
	}
	return max
}

// columnLeft moves the column cursor left.
func (root *Root) columnLeft(n int) {
	m := root.Doc
	root.prepareScreen()
	if m.columnCursor > 0 {
		m.columnCursor--
	} else if !root.Config.DisableColumnCycle {
		c := root.columnCount(m)
		if c > 0 {
			m.columnCursor = c - 1
		}
	}
	root.adjustColumnX(m)
}

// columnRight moves the column cursor right.
func (root *Root) columnRight(n int) {
	m := root.Doc
	root.prepareScreen()
	c := root.columnCount(m)
	if m.columnCursor < c-1 {
		m.columnCursor++
	} else if !root.Config.DisableColumnCycle {
		m.columnCursor = 0
	}
	root.adjustColumnX(m)
}

// columnEnd moves to the last column.
func (root *Root) columnEnd() {
	m := root.Doc
	c := root.columnCount(m)
	if c > 0 {
		m.columnCursor = c - 1
	}
	root.adjustColumnX(m)
}

// adjustColumnX scrolls horizontally so the current column is visible.
func (root *Root) adjustColumnX(m *Document) {
	if m.RunTimeSettings.WrapMode {
		return
	}
	width := root.scr.bodyWidth()
	// use the first valid row to find the column position
	for _, r := range root.scr.rows {
		if !r.valid {
			continue
		}
		ranges := m.columnRanges(m.getContents(r.number))
		if m.columnCursor >= len(ranges) {
			continue
		}
		cr := ranges[m.columnCursor]
		if cr[0] < m.x {
			m.x = cr[0]
		} else if cr[1] > m.x+width {
			m.x = cr[1] - width
			if cr[0] < m.x {
				m.x = cr[0]
			}
		}
		if m.x < 0 {
			m.x = 0
		}
		return
	}
}

