package oviewer

import (
	"os"
	"time"
)

// followAllUpdate switches to the most recently updated document.
func (root *Root) followAllUpdate() {
	if root.Doc.docType == docHelp || root.Doc.docType == docLog {
		return
	}
	for i, m := range root.DocList {
		if m.BufEndNum() != m.latestNum && m.latestNum >= 0 {
			if i != root.CurrentDoc {
				root.CurrentDoc = i
				root.Doc = m
			}
			m.latestNum = m.BufEndNum()
			root.moveBottomDoc(m)
			return
		}
		if m.latestNum < 0 {
			m.latestNum = m.BufEndNum()
		}
	}
}

// startWatch starts a timer that reloads the document periodically.
func (root *Root) startWatch(m *Document, interval int) {
	if interval <= 0 {
		return
	}
	go func() {
		t := time.NewTicker(time.Duration(interval) * time.Second)
		defer t.Stop()
		for range t.C {
			if !m.WatchMode {
				return
			}
			root.Screen.PostEvent(&eventReload{doc: m})
		}
	}()
}

// followFile keeps reading a regular file in follow mode (tail -f like).
func (m *Document) followFile(path string) {
	go func() {
		for {
			time.Sleep(100 * time.Millisecond)
			if m.closed {
				return
			}
			f := m.file
			if f == nil {
				return
			}
			st, err := f.Stat()
			if err != nil {
				continue
			}
			pos, err := f.Seek(0, 1)
			if err != nil {
				continue
			}
			if st.Size() > pos {
				m.readSync(f)
			} else if st.Size() < pos {
				// truncated
				f.Seek(0, 0)
				m.reset()
				m.readSync(f)
			}
			if m.FollowName {
				if nst, err := os.Stat(path); err == nil && !os.SameFile(nst, st) {
					if nf, err := os.Open(path); err == nil {
						f.Close()
						m.file = nf
						m.reset()
						m.readSync(nf)
					}
				}
			}
		}
	}()
}
