// writeOriginalOut writes the lines currently displayed (plus the
// configured number of lines before and after) to w.
func (root *Root) writeOriginalOut(w io.Writer) error {
	m := root.Doc
	root.prepareScreen()
	bw := bufio.NewWriter(w)
	defer bw.Flush()
	start := m.topLN - root.BeforeWriteOriginal
	if start < 0 {
		start = 0
	}
	// header lines
	for ln := root.scr.headerLN; ln < root.scr.headerEnd; ln++ {
		if ln >= m.BufEndNum() {
			break
		}
		bw.WriteString(m.GetLine(ln))
		bw.WriteString("\n")
	}
	// body lines currently on screen
	last := -1
	for _, r := range root.scr.rows[root.scr.headerRows:] {
		if !r.valid {
			continue
		}
		last = r.number
	}
	if last < 0 {
		last = m.topLN - 1
	}
	end := last + root.AfterWriteOriginal
	if end >= m.BufEndNum() {
		end = m.BufEndNum() - 1
	}
	for ln := start; ln <= end; ln++ {
		if ln < root.scr.headerEnd && ln >= root.scr.headerLN {
			continue
		}
		bw.WriteString(m.GetLine(ln))
		bw.WriteString("\n")
	}
	return nil
}

// toANSI converts contents to a string with ANSI escape sequences.
func toANSI(lc contents) string {
	var b strings.Builder
	prev := tcell.StyleDefault
	for _, c := range lc {
		if c.mainc == cellPlaceholder {
			continue
		}
		if c.style != prev {
			b.WriteString("\x1b[0m")
			prev = c.style
		}
		b.WriteRune(c.mainc)
	}
	if prev != tcell.StyleDefault {
		b.WriteString("\x1b[0m")
	}
	return b.String()
}
