package oviewer

import (
	"os"
	"strings"

	"github.com/gdamore/tcell/v2"
	"github.com/gdamore/tcell/v2/terminfo"
	_ "github.com/gdamore/tcell/v2/terminfo/x/xterm"
)

// terminalColors decides the color capability of the terminal from $TERM.
// Returns the number of colors (0, 8, 256) and whether true color is enabled.
func terminalColors(term string) (int, bool) {
	t := strings.ToLower(term)
	switch {
	case strings.Contains(t, "truecolor"), strings.Contains(t, "direct"):
		return 256, true
	case strings.Contains(t, "256color"):
		return 256, false
	case strings.Contains(t, "mono"), strings.HasSuffix(t, "-m"):
		return 0, false
	case strings.HasPrefix(t, "vt"):
		return 0, false
	case strings.Contains(t, "color"):
		return 8, false
	case strings.Contains(t, "ansi"):
		return 8, false
	}
	switch t {
	case "xterm", "linux", "dtterm", "aixterm":
		return 8, false
	case "sun":
		return 0, false
	}
	return 256, false
}

// newScreen creates the tcell screen with a terminfo definition derived
// from the xterm family and the color heuristics.
func newScreen() (tcell.Screen, error) {
	term := os.Getenv("TERM")
	base, err := terminfo.LookupTerminfo("xterm-256color")
	if err != nil {
		return tcell.NewScreen()
	}
	ti := *base
	ti.Name = term
	if term == "" {
		ti.Name = "xterm-256color"
	}
	ti.Aliases = nil
	colors, truecolor := terminalColors(term)
	switch colors {
	case 0:
		ti.Colors = 0
		ti.SetFg = ""
		ti.SetBg = ""
		ti.SetFgBg = ""
		ti.SetFgRGB = ""
		ti.SetBgRGB = ""
		ti.SetFgBgRGB = ""
	case 8:
		ti.Colors = 8
		ti.SetFg = "\x1b[3%p1%dm"
		ti.SetBg = "\x1b[4%p1%dm"
		ti.SetFgBg = "\x1b[3%p1%d;4%p2%dm"
		ti.SetFgRGB = ""
		ti.SetBgRGB = ""
		ti.SetFgBgRGB = ""
	default:
		ti.Colors = 256
		ti.SetFgRGB = ""
		ti.SetBgRGB = ""
		ti.SetFgBgRGB = ""
		if truecolor {
			ti.SetFgRGB = "\x1b[38;2;%p1%d;%p2%d;%p3%dm"
			ti.SetBgRGB = "\x1b[48;2;%p1%d;%p2%d;%p3%dm"
			ti.SetFgBgRGB = "\x1b[38;2;%p1%d;%p2%d;%p3%d;48;2;%p4%d;%p5%d;%p6%dm"
		}
	}
	switch os.Getenv("COLORTERM") {
	case "truecolor", "24bit", "24-bit":
		if colors > 0 {
			ti.SetFgRGB = "\x1b[38;2;%p1%d;%p2%d;%p3%dm"
			ti.SetBgRGB = "\x1b[48;2;%p1%d;%p2%d;%p3%dm"
			ti.SetFgBgRGB = "\x1b[38;2;%p1%d;%p2%d;%p3%d;48;2;%p4%d;%p5%d;%p6%dm"
		}
	}
	return tcell.NewTerminfoScreenFromTtyTerminfo(nil, &ti)
}
