// flagUsages renders the flag usage lines like pflag does, except that
// boolean flags accepting an optional value are shown as "[=true|false]".
func flagUsages(f *pflag.FlagSet) string {
	var lines []string
	maxlen := 0
	f.VisitAll(func(flag *pflag.Flag) {
		if flag.Hidden {
			return
		}
		var line string
		if flag.Shorthand != "" && flag.ShorthandDeprecated == "" {
			line = fmt.Sprintf("  -%s, --%s", flag.Shorthand, flag.Name)
		} else {
			line = fmt.Sprintf("      --%s", flag.Name)
		}
		varname, usage := pflag.UnquoteUsage(flag)
		if varname != "" {
			line += " " + varname
		}
		if flag.NoOptDefVal != "" {
			switch flag.Value.Type() {
			case "bool":
				line += "[=true|false]"
			}
		}
		// The special character '\\x00' is used to split the line into name and usage.
		line += "\\x00"
		if len(line) > maxlen {
			maxlen = len(line)
		}
		line += usage
		if !defaultIsZeroValue(flag) {
			if flag.Value.Type() == "string" {
				line += fmt.Sprintf(" (default %q)", flag.DefValue)
			} else {
				line += fmt.Sprintf(" (default %s)", flag.DefValue)
			}
		}
		if len(flag.Deprecated) != 0 {
			line += fmt.Sprintf(" (DEPRECATED: %s)", flag.Deprecated)
		}
		lines = append(lines, line)
	})
	var b strings.Builder
	for _, line := range lines {
		sidx := strings.Index(line, "\\x00")
		spacing := strings.Repeat(" ", maxlen-sidx)
		b.WriteString(line[:sidx])
