// Package zstd implements a zstandard (RFC 8878) decompressor.
package zstd

import "errors"

var errCorrupt = errors.New("zstd: corrupt data")

// bitReader reads bits backwards (from the end of the buffer), as used
// by the zstd entropy coders.
type bitReader struct {
	data  []byte
	off   int // byte offset of the next byte to load (going backwards)
	value uint64
	bits  uint // number of valid bits in value
}

// newBitReader initializes a reverse bit reader over data; the last byte
// contains the padding marker bit.
func newBitReader(data []byte) (*bitReader, error) {
	if len(data) == 0 {
		return nil, errCorrupt
	}
	br := &bitReader{data: data, off: len(data)}
	// load initial bits
	br.refill()
	// skip padding: find the highest set bit of the last byte
	last := data[len(data)-1]
	if last == 0 {
		return nil, errCorrupt
	}
	pad := 0
	for b := last; b&0x80 == 0; b <<= 1 {
		pad++
	}
	br.bits -= uint(pad + 1)
	return br, nil
}

// refill loads bytes into value so that at least 56 bits are available
// (if data remains).
func (br *bitReader) refill() {
	for br.bits <= 56 && br.off > 0 {
		br.off--
		br.value = (br.value << 8) | uint64(br.data[br.off])
		br.bits += 8
	}
}

// readBits reads n bits (n <= 32). If not enough bits remain, zeros are
// supplied (as permitted when the stream is exhausted).
func (br *bitReader) readBits(n uint) uint32 {
	if n == 0 {
		return 0
	}
	if br.bits < n {
		br.refill()
	}
	if br.bits < n {
		// pad with zeros
		v := (br.value << (n - br.bits)) & ((1 << n) - 1)
		br.bits = 0
		br.value = 0
		br.overread += n
		return uint32(v)
	}
	br.bits -= n
	v := (br.value >> br.bits) & ((1 << n) - 1)
	return uint32(v)
}

// peekBits returns the next n bits without consuming them.
func (br *bitReader) peekBits(n uint) uint32 {
	if n == 0 {
		return 0
	}
	if br.bits < n {
		br.refill()
	}
	if br.bits < n {
		v := (br.value << (n - br.bits)) & ((1 << n) - 1)
		return uint32(v)
	}
	return uint32((br.value >> (br.bits - n)) & ((1 << n) - 1))
}

func (br *bitReader) skip(n uint) {
	if br.bits < n {
		br.refill()
	}
	if br.bits < n {
		br.overread += n - br.bits
		br.bits = 0
		return
	}
	br.bits -= n
}

// finished reports whether all bits have been consumed.
func (br *bitReader) finished() bool {
	return br.off == 0 && br.bits == 0
}

// remaining returns the remaining number of bits.
func (br *bitReader) remaining() int {
	return int(br.bits) + br.off*8
}
