package zstd

// fseEntry is one decoding table entry.
type fseEntry struct {
	symbol  uint8
	nbBits  uint8
	newState uint16
	// baseline/extra bits for sequence codes are looked up elsewhere.
}

// fseTable is an FSE decoding table.
type fseTable struct {
	accuracyLog uint
	table       []fseEntry
}

// readFSETable parses an FSE table description from data (forward bit order).
// It returns the table and the number of bytes consumed.
func readFSETable(data []byte, maxLog uint, maxSymbol int) (*fseTable, int, error) {
	if len(data) < 1 {
		return nil, 0, errCorrupt
	}
	// forward bit reader
	bitPos := 0
	readBits := func(n int) (uint32, error) {
		var v uint32
		for i := 0; i < n; i++ {
			byteIdx := bitPos >> 3
			if byteIdx >= len(data) {
				return 0, errCorrupt
			}
			bit := (data[byteIdx] >> (bitPos & 7)) & 1
			v |= uint32(bit) << i
			bitPos++
		}
		return v, nil
	}
	peekBits := func(n int) uint32 {
		var v uint32
		p := bitPos
		for i := 0; i < n; i++ {
			byteIdx := p >> 3
			var bit byte
			if byteIdx < len(data) {
				bit = (data[byteIdx] >> (p & 7)) & 1
			}
			v |= uint32(bit) << i
			p++
		}
		return v
	}
	al, err := readBits(4)
	if err != nil {
		return nil, 0, err
	}
	accuracyLog := uint(al) + 5
	if accuracyLog > maxLog {
		return nil, 0, errCorrupt
	}
	tableSize := 1 << accuracyLog
	remaining := int32(tableSize) + 1
	probs := make([]int16, 0, maxSymbol+1)
	for remaining > 1 && len(probs) <= maxSymbol {
		// number of bits needed
		nbBits := bitsNeeded(uint32(remaining))
		threshold := uint32(1<<nbBits) - uint32(remaining)
		low := peekBits(nbBits - 1)
		var val uint32
		if low < threshold {
			val = low
			bitPos += nbBits - 1
		} else {
			v := peekBits(nbBits)
			bitPos += nbBits
			if v >= uint32(1<<(nbBits-1)) {
				val = v - threshold
			} else {
				val = v
			}
		}
		prob := int32(val) - 1
		remaining -= absInt32(prob)
		if prob == 0 {
			// repeat zeros: 2 bits
			for {
				rep, err := readBits(2)
				if err != nil {
					return nil, 0, err
				}
				for i := uint32(0); i < rep; i++ {
					probs = append(probs, 0)
				}
				if rep < 3 {
					break
				}
			}
			probs = append(probs, 0)
			continue
		}
		probs = append(probs, int16(prob))
	}
	if remaining != 1 {
		return nil, 0, errCorrupt
	}
	// consumed bytes
	consumed := (bitPos + 7) >> 3
	t, err := buildFSETable(probs, accuracyLog)
	if err != nil {
		return nil, 0, err
	}
