// buildFSETable builds the decoding table from normalized probabilities.
func buildFSETable(probs []int16, accuracyLog uint) (*fseTable, error) {
	tableSize := 1 << accuracyLog
	table := make([]fseEntry, tableSize)
	symbolNext := make([]uint16, len(probs))
	// place "less than 1" probabilities at the end
	highThreshold := tableSize - 1
	for s, p := range probs {
		if p == -1 {
