			return nil, 0, err
		}
		var s1, s2 fseState
		s1.t = table
		s2.t = table
		s1.init(br)
		s2.init(br)
		for {
			if br.overread > 0 || len(weights) > 255 {
				break
			}
			weights = append(weights, s1.symbol())
			if br.remaining() < int(table.accuracyLog) && br.off == 0 {
				// Even state: check end
			}
			s1.update(br)
			if br.overread > 0 {
				// s1 consumed beyond end: s2 symbol is still valid
				weights = append(weights, s2.symbol())
				break
			}
			weights = append(weights, s2.symbol())
			s2.update(br)
			if br.overread > 0 {
				weights = append(weights, s1.symbol())
				break
			}
			if br.finished() {
				// both states have been updated with all bits; the final
				// symbols are read in the loop normally
			}
		}
		consumed += compSize
	} else {
		num := headerByte - 127
		nbytes := (num + 1) / 2
		if len(data) < 1+nbytes {
			return nil, 0, errCorrupt
		}
		weights = make([]uint8, 0, num)
		for i := 0; i < num; i++ {
			b := data[1+i/2]
			if i%2 == 0 {
				weights = append(weights, b>>4)
			} else {
				weights = append(weights, b&0x0f)
			}
		}
		consumed += nbytes
	}
	t, err := buildHuffTable(weights)
	if err != nil {
		return nil, 0, err
	}
	return t, consumed, nil
}

// buildHuffTable builds the decoding table from weights (the last weight is implied).
func buildHuffTable(weights []uint8) (*huffTable, error) {
	if len(weights) == 0 || len(weights) > 255 {
		return nil, errCorrupt
	}
	sum := 0
	for _, w := range weights {
		if w > 11 {
			return nil, errCorrupt
		}
		if w > 0 {
			sum += 1 << (w - 1)
		}
	}
	if sum == 0 {
		return nil, errCorrupt
	}
	// maxBits = bitsNeeded(sum) ; the last weight fills to a power of two
	maxBits := uint(bitsNeeded(uint32(sum)))
	total := 1 << maxBits
	left := total - sum
	if left <= 0 {
		return nil, errCorrupt
	}
	// left must be a power of two
	if left&(left-1) != 0 {
		return nil, errCorrupt
	}
	lastWeight := uint8(bitsNeeded(uint32(left)))
	weights = append(weights, lastWeight)
	numSyms := len(weights)
	// number of bits per symbol = maxBits + 1 - weight
	t := &huffTable{maxBits: maxBits, symbols: make([]uint8, total), lengths: make([]uint8, total)}
	// assign codes: symbols sorted by weight ascending then symbol value
	// (canonical). In zstd, codes are assigned in order of increasing
	// weight (i.e. decreasing bit length), lowest weight first.
	pos := 0
	for w := uint8(1); w <= uint8(maxBits); w++ {
		nbits := maxBits + 1 - uint(w)
		count := 1 << (maxBits - nbits) // number of table entries per symbol
		for s := 0; s < numSyms; s++ {
			if weights[s] != w {
				continue
			}
			for i := 0; i < count; i++ {
				if pos >= total {
					return nil, errCorrupt
				}
				t.symbols[pos] = uint8(s)
				t.lengths[pos] = uint8(nbits)
				pos++
			}
		}
	}
	if pos != total {
		return nil, errCorrupt
	}
	return t, nil
}

// decodeStream decodes a Huffman stream into dst (exactly n symbols).
func (t *huffTable) decodeStream(data []byte, dst []byte) error {
	br, err := newBitReader(data)
	if err != nil {
		return err
	}
	for i := range dst {
		idx := br.peekBits(t.maxBits)
		dst[i] = t.symbols[idx]
		br.skip(uint(t.lengths[idx]))
		if br.overread > t.maxBits {
			return errCorrupt
		}
	}
	return nil
}
