// decodeCompressedBlock decodes a compressed block.
func (z *Reader) decodeCompressedBlock(block []byte) ([]byte, error) {
	literals, n, err := z.decodeLiterals(block)
	if err != nil {
		return nil, err
	}
	seqData := block[n:]
	return z.decodeSequences(seqData, literals)
}

// decodeLiterals decodes the literals section and returns the literals and
// the number of bytes consumed.
func (z *Reader) decodeLiterals(block []byte) ([]byte, int, error) {
	if len(block) < 1 {
		return nil, 0, errCorrupt
	}
	b0 := block[0]
	ltype := b0 & 3
	sizeFormat := (b0 >> 2) & 3
	switch ltype {
	case 0, 1: // raw / RLE
		var regSize, hdrSize int
		switch sizeFormat {
		case 0, 2:
			regSize = int(b0 >> 3)
			hdrSize = 1
		case 1:
			if len(block) < 2 {
				return nil, 0, errCorrupt
			}
			regSize = int(b0>>4) | int(block[1])<<4
			hdrSize = 2
		case 3:
			if len(block) < 3 {
				return nil, 0, errCorrupt
			}
			regSize = int(b0>>4) | int(block[1])<<4 | int(block[2])<<12
			hdrSize = 3
		}
		if ltype == 0 {
			if len(block) < hdrSize+regSize {
				return nil, 0, errCorrupt
			}
			lit := make([]byte, regSize)
			copy(lit, block[hdrSize:hdrSize+regSize])
			return lit, hdrSize + regSize, nil
		}
		if len(block) < hdrSize+1 {
			return nil, 0, errCorrupt
		}
		lit := make([]byte, regSize)
		for i := range lit {
			lit[i] = block[hdrSize]
		}
		return lit, hdrSize + 1, nil
	}
	// compressed (2) or treeless (3)
	var regSize, compSize, hdrSize, streams int
	switch sizeFormat {
	case 0, 1:
		if len(block) < 3 {
			return nil, 0, errCorrupt
		}
		v := uint32(b0) | uint32(block[1])<<8 | uint32(block[2])<<16
		regSize = int((v >> 4) & 0x3ff)
		compSize = int((v >> 14) & 0x3ff)
		hdrSize = 3
		if sizeFormat == 0 {
			streams = 1
		} else {
			streams = 4
		}
	case 2:
		if len(block) < 4 {
			return nil, 0, errCorrupt
		}
		v := uint32(b0) | uint32(block[1])<<8 | uint32(block[2])<<16 | uint32(block[3])<<24
		regSize = int((v >> 4) & 0x3fff)
		compSize = int((v >> 18) & 0x3fff)
		hdrSize = 4
		streams = 4
	case 3:
		if len(block) < 5 {
			return nil, 0, errCorrupt
		}
		v := uint64(b0) | uint64(block[1])<<8 | uint64(block[2])<<16 | uint64(block[3])<<24 | uint64(block[4])<<32
		regSize = int((v >> 4) & 0x3ffff)
		compSize = int((v >> 22) & 0x3ffff)
		hdrSize = 5
		streams = 4
	}
	if len(block) < hdrSize+compSize {
		return nil, 0, errCorrupt
	}
	data := block[hdrSize : hdrSize+compSize]
	if ltype == 2 {
		t, n, err := readHuffmanTable(data)
		if err != nil {
			return nil, 0, err
		}
		z.huff = t
		data = data[n:]
	} else if z.huff == nil {
		return nil, 0, errCorrupt
	}
	lit := make([]byte, regSize)
	if streams == 1 {
		if err := z.huff.decodeStream(data, lit); err != nil {
			return nil, 0, err
		}
		return lit, hdrSize + compSize, nil
	}
	// 4 streams: jump table of 3 uint16
	if len(data) < 6 {
		return nil, 0, errCorrupt
	}
	s1 := int(binary.LittleEndian.Uint16(data[0:2]))
	s2 := int(binary.LittleEndian.Uint16(data[2:4]))
	s3 := int(binary.LittleEndian.Uint16(data[4:6]))
	rest := data[6:]
	if s1+s2+s3 > len(rest) {
		return nil, 0, errCorrupt
	}
	segSize := (regSize + 3) / 4
	streamsData := [][]byte{rest[:s1], rest[s1 : s1+s2], rest[s1+s2 : s1+s2+s3], rest[s1+s2+s3:]}
	for i := 0; i < 4; i++ {
		start := i * segSize
		end := start + segSize
		if i == 3 {
			end = regSize
		}
		if start > regSize {
			start = regSize
		}
		if end > regSize {
			end = regSize
		}
		if end <= start {
			continue
		}
		if err := z.huff.decodeStream(streamsData[i], lit[start:end]); err != nil {
			return nil, 0, err
		}
	}
	return lit, hdrSize + compSize, nil
}

// readSeqTable reads a sequence table according to the mode.
func (z *Reader) readSeqTable(data []byte, mode byte, def *fseTable, prev *fseTable, maxLog uint, maxSym int) (*fseTable, int, error) {
	switch mode {
	case 0:
		return def, 0, nil
	case 1:
		if len(data) < 1 {
			return nil, 0, errCorrupt
		}
		return rleTable(data[0]), 1, nil
	case 2:
		t, n, err := readFSETable(data, maxLog, maxSym)
		return t, n, err
	default:
		if prev == nil {
			return nil, 0, errCorrupt
		}
		return prev, 0, nil
	}
}

// decodeSequences decodes the sequences section and executes them.
func (z *Reader) decodeSequences(data []byte, literals []byte) ([]byte, error) {
	if len(data) < 1 {
		return nil, errCorrupt
	}
	var numSeq int
	b0 := int(data[0])
	pos := 1
	switch {
	case b0 == 0:
		numSeq = 0
	case b0 < 128:
		numSeq = b0
	case b0 < 255:
		if len(data) < 2 {
			return nil, errCorrupt
		}
		numSeq = (b0-128)<<8 | int(data[1])
		pos = 2
	default:
		if len(data) < 3 {
			return nil, errCorrupt
		}
		numSeq = int(data[1]) | int(data[2])<<8 + 0x7f00
		pos = 3
	}
	if numSeq == 0 {
		// only literals
		return literals, nil
	}
	if len(data) < pos+1 {
		return nil, errCorrupt
	}
	modes := data[pos]
	pos++
	llMode := (modes >> 6) & 3
	ofMode := (modes >> 4) & 3
	mlMode := (modes >> 2) & 3
	var err error
	var n int
	z.llTable, n, err = z.readSeqTable(data[pos:], llMode, llDefault, z.llTable, 9, 35)
	if err != nil {
		return nil, err
	}
	pos += n
	z.ofTable, n, err = z.readSeqTable(data[pos:], ofMode, ofDefault, z.ofTable, 8, 31)
	if err != nil {
		return nil, err
	}
	pos += n
	z.mlTable, n, err = z.readSeqTable(data[pos:], mlMode, mlDefault, z.mlTable, 9, 52)
	if err != nil {
		return nil, err
	}
	pos += n
	if pos > len(data) {
		return nil, errCorrupt
	}
	br, err := newBitReader(data[pos:])
	if err != nil {
		return nil, err
	}
	var llS, ofS, mlS fseState
	llS.t, ofS.t, mlS.t = z.llTable, z.ofTable, z.mlTable
	llS.init(br)
	ofS.init(br)
	mlS.init(br)

	out := make([]byte, 0, len(literals)*4+64)
	litPos := 0
	// history: window + current out
	for i := 0; i < numSeq; i++ {
		llCode := llS.symbol()
		ofCode := ofS.symbol()
		mlCode := mlS.symbol()
		if int(llCode) >= len(llBaseline) || int(mlCode) >= len(mlBaseline) || ofCode > 31 {
			return nil, errCorrupt
		}
		// offset first
		ofValue := (1 << ofCode) + int(br.readBits(uint(ofCode)))
		ml := int(mlBaseline[mlCode]) + int(br.readBits(uint(mlBits[mlCode])))
		ll := int(llBaseline[llCode]) + int(br.readBits(uint(llBits[llCode])))
		// repeat offsets
		var offset int
		if ofValue > 3 {
			offset = ofValue - 3
			z.repOffsets[2] = z.repOffsets[1]
			z.repOffsets[1] = z.repOffsets[0]
			z.repOffsets[0] = offset
		} else {
			idx := ofValue - 1
			if ll == 0 {
				idx++
			}
			switch idx {
			case 0:
				offset = z.repOffsets[0]
			case 1:
				offset = z.repOffsets[1]
				z.repOffsets[1] = z.repOffsets[0]
				z.repOffsets[0] = offset
			case 2:
				offset = z.repOffsets[2]
				z.repOffsets[2] = z.repOffsets[1]
				z.repOffsets[1] = z.repOffsets[0]
				z.repOffsets[0] = offset
			case 3:
				offset = z.repOffsets[0] - 1
				if offset < 1 {
					return nil, errCorrupt
				}
				z.repOffsets[2] = z.repOffsets[1]
				z.repOffsets[1] = z.repOffsets[0]
				z.repOffsets[0] = offset
			}
		}
		// copy literals
		if litPos+ll > len(literals) {
			return nil, errCorrupt
		}
		out = append(out, literals[litPos:litPos+ll]...)
		litPos += ll
		// copy match
		total := len(z.window) + len(out)
		if offset > total || offset <= 0 {
			return nil, errCorrupt
		}
		for k := 0; k < ml; k++ {
			srcIdx := len(z.window) + len(out) - offset
			var b byte
			if srcIdx < len(z.window) {
				b = z.window[srcIdx]
			} else {
				b = out[srcIdx-len(z.window)]
			}
			out = append(out, b)
		}
		// update states (unless last)
		if i+1 < numSeq {
			llS.update(br)
			mlS.update(br)
			ofS.update(br)
		}
	}
	// remaining literals
	out = append(out, literals[litPos:]...)
	return out, nil
}
