package zstd

import (
	"bufio"
	"encoding/binary"
	"errors"
	"io"
)

// Reader decompresses a zstd stream.
type Reader struct {
	br  *bufio.Reader
	out []byte // decoded data not yet returned
	err error

	window     []byte // history for match copies
	windowSize int

	// repeat offsets
	repOffsets [3]int

	// entropy tables kept between blocks (repeat mode)
	huff    *huffTable
	llTable *fseTable
	ofTable *fseTable
	mlTable *fseTable

	inFrame     bool
	contentLeft int64
	hasChecksum bool
	frameDone   bool
}

// NewReader returns a new zstd reader.
func NewReader(r io.Reader) *Reader {
	return &Reader{br: bufio.NewReaderSize(r, 1<<16)}
}

// Read implements io.Reader.
func (z *Reader) Read(p []byte) (int, error) {
	for len(z.out) == 0 {
		if z.err != nil {
			return 0, z.err
		}
		if err := z.step(); err != nil {
			z.err = err
			if len(z.out) == 0 {
				return 0, err
			}
		}
	}
	n := copy(p, z.out)
	z.out = z.out[n:]
	return n, nil
}

// step decodes the next frame header or block.
func (z *Reader) step() error {
	if !z.inFrame {
		return z.readFrameHeader()
	}
	return z.readBlock()
}

func (z *Reader) readFrameHeader() error {
	var magic [4]byte
	if _, err := io.ReadFull(z.br, magic[:]); err != nil {
		if err == io.ErrUnexpectedEOF {
			return io.EOF
		}
		return err
	}
	m := binary.LittleEndian.Uint32(magic[:])
	if m >= 0x184D2A50 && m <= 0x184D2A5F {
		// skippable frame
		var sz [4]byte
		if _, err := io.ReadFull(z.br, sz[:]); err != nil {
			return errCorrupt
		}
		n := binary.LittleEndian.Uint32(sz[:])
		if _, err := io.CopyN(io.Discard, z.br, int64(n)); err != nil {
			return errCorrupt
		}
		return nil
	}
	if m != 0xFD2FB528 {
		return errors.New("zstd: invalid magic number")
	}
	fhd, err := z.br.ReadByte()
	if err != nil {
		return errCorrupt
	}
	fcsFlag := fhd >> 6
	singleSegment := fhd&0x20 != 0
	z.hasChecksum = fhd&0x04 != 0
	dictFlag := fhd & 0x03
	windowSize := 0
	if !singleSegment {
		wd, err := z.br.ReadByte()
		if err != nil {
			return errCorrupt
		}
		exp := int(wd >> 3)
		mant := int(wd & 7)
		base := 1 << (10 + exp)
		windowSize = base + (base/8)*mant
	}
	switch dictFlag {
	case 1:
		z.br.Discard(1)
	case 2:
		z.br.Discard(2)
	case 3:
		z.br.Discard(4)
	}
	var fcsSize int
	switch fcsFlag {
	case 0:
		if singleSegment {
			fcsSize = 1
		}
	case 1:
		fcsSize = 2
	case 2:
		fcsSize = 4
	case 3:
		fcsSize = 8
	}
	z.contentLeft = -1
	if fcsSize > 0 {
		var b [8]byte
		if _, err := io.ReadFull(z.br, b[:fcsSize]); err != nil {
			return errCorrupt
		}
		var fcs uint64
		switch fcsSize {
		case 1:
			fcs = uint64(b[0])
		case 2:
			fcs = uint64(binary.LittleEndian.Uint16(b[:2])) + 256
		case 4:
			fcs = uint64(binary.LittleEndian.Uint32(b[:4]))
		case 8:
			fcs = binary.LittleEndian.Uint64(b[:8])
		}
		z.contentLeft = int64(fcs)
		if singleSegment {
			windowSize = int(fcs)
		}
	}
	if windowSize <= 0 {
		windowSize = 1 << 20
	}
	if windowSize > 1<<30 {
		return errors.New("zstd: window size too large")
	}
	z.windowSize = windowSize
	z.window = z.window[:0]
	z.repOffsets = [3]int{1, 4, 8}
	z.huff = nil
	z.llTable, z.ofTable, z.mlTable = nil, nil, nil
	z.inFrame = true
	return nil
}

func (z *Reader) readBlock() error {
	var hdr [3]byte
	if _, err := io.ReadFull(z.br, hdr[:]); err != nil {
		return errCorrupt
	}
	h := uint32(hdr[0]) | uint32(hdr[1])<<8 | uint32(hdr[2])<<16
	last := h&1 != 0
	btype := (h >> 1) & 3
	size := int(h >> 3)
	var decoded []byte
	switch btype {
	case 0: // raw
		buf := make([]byte, size)
		if _, err := io.ReadFull(z.br, buf); err != nil {
			return errCorrupt
		}
		decoded = buf
	case 1: // RLE
		b, err := z.br.ReadByte()
		if err != nil {
			return errCorrupt
		}
		decoded = make([]byte, size)
		for i := range decoded {
			decoded[i] = b
		}
	case 2: // compressed
		buf := make([]byte, size)
		if _, err := io.ReadFull(z.br, buf); err != nil {
			return errCorrupt
		}
		var err error
		decoded, err = z.decodeCompressedBlock(buf)
		if err != nil {
			return err
		}
	default:
		return errCorrupt
	}
	z.appendOutput(decoded)
	if last {
		if z.hasChecksum {
			z.br.Discard(4)
		}
		z.inFrame = false
	}
	return nil
}

// appendOutput appends decoded data to the output and the window.
func (z *Reader) appendOutput(b []byte) {
	z.out = append(z.out, b...)
	z.window = append(z.window, b...)
	if len(z.window) > z.windowSize*2+1<<17 {
		keep := z.windowSize
		copy(z.window, z.window[len(z.window)-keep:])
		z.window = z.window[:keep]
	}
}

