}

// decodeLiterals decodes the literals section and returns the literals and
// the number of bytes consumed.
func (z *Reader) decodeLiterals(block []byte) ([]byte, int, error) {
	if len(block) < 1 {
		return nil, 0, errCorrupt
	}
	b0 := block[0]
	ltype := b0 & 3
	sizeFormat := (b0 >> 2) & 3
	switch ltype {
	case 0, 1: // raw / RLE
		var regSize, hdrSize int
		switch sizeFormat {
		case 0, 2:
			regSize = int(b0 >> 3)
			hdrSize = 1
		case 1:
			if len(block) < 2 {
				return nil, 0, errCorrupt
			}
			regSize = int(b0>>4) | int(block[1])<<4
			hdrSize = 2
		case 3:
			if len(block) < 3 {
				return nil, 0, errCorrupt
			}
			regSize = int(b0>>4) | int(block[1])<<4 | int(block[2])<<12
			hdrSize = 3
		}
		if ltype == 0 {
			if len(block) < hdrSize+regSize {
				return nil, 0, errCorrupt
			}
			lit := make([]byte, regSize)
			copy(lit, block[hdrSize:hdrSize+regSize])
			return lit, hdrSize + regSize, nil
		}
		if len(block) < hdrSize+1 {
			return nil, 0, errCorrupt
		}
		lit := make([]byte, regSize)
		for i := range lit {
			lit[i] = block[hdrSize]
		}
		return lit, hdrSize + 1, nil
	}
	// compressed (2) or treeless (3)
	var regSize, compSize, hdrSize, streams int
	switch sizeFormat {
	case 0, 1:
		if len(block) < 3 {
			return nil, 0, errCorrupt
		}
		v := uint32(b0) | uint32(block[1])<<8 | uint32(block[2])<<16
		regSize = int((v >> 4) & 0x3ff)
		compSize = int((v >> 14) & 0x3ff)
		hdrSize = 3
		if sizeFormat == 0 {
			streams = 1
		} else {
			streams = 4
		}
	case 2:
		if len(block) < 4 {
			return nil, 0, errCorrupt
		}
		v := uint32(b0) | uint32(block[1])<<8 | uint32(block[2])<<16 | uint32(block[3])<<24
		regSize = int((v >> 4) & 0x3fff)
		compSize = int((v >> 18) & 0x3fff)
		hdrSize = 4
		streams = 4
	case 3:
		if len(block) < 5 {
			return nil, 0, errCorrupt
		}
		v := uint64(b0) | uint64(block[1])<<8 | uint64(block[2])<<16 | uint64(block[3])<<24 | uint64(block[4])<<32
		regSize = int((v >> 4) & 0x3ffff)
		compSize = int((v >> 22) & 0x3ffff)
		hdrSize = 5
		streams = 4
	}
	if len(block) < hdrSize+compSize {
		return nil, 0, errCorrupt
