// readSeqTable reads a sequence table according to the mode.
func (z *Reader) readSeqTable(data []byte, mode byte, def *fseTable, prev *fseTable, maxLog uint, maxSym int) (*fseTable, int, error) {
	switch mode {
	case 0:
		return def, 0, nil
	case 1:
		if len(data) < 1 {
			return nil, 0, errCorrupt
		}
		return rleTable(data[0]), 1, nil
	case 2:
		t, n, err := readFSETable(data, maxLog, maxSym)
		return t, n, err
	default:
		if prev == nil {
			return nil, 0, errCorrupt
		}
		return prev, 0, nil
	}
}

// decodeSequences decodes the sequences section and executes them.
func (z *Reader) decodeSequences(data []byte, literals []byte) ([]byte, error) {
