		ml := int(mlBaseline[mlCode]) + int(br.readBits(uint(mlBits[mlCode])))
		ll := int(llBaseline[llCode]) + int(br.readBits(uint(llBits[llCode])))
		// repeat offsets
		var offset int
		if ofValue > 3 {
			offset = ofValue - 3
