// readIndexAndFooter skips the index and the stream footer.
func (z *Reader) readIndexAndFooter() error {
	// index: number of records
	buf := make([]byte, 0, 16)
	readVLIStream := func() (uint64, error) {
		buf = buf[:0]
		for {
			b, err := z.br.ReadByte()
			if err != nil {
				return 0, errCorrupt
			}
			buf = append(buf, b)
			if b&0x80 == 0 {
				v, _, err := readVLI(buf)
				return v, err
			}
			if len(buf) > 9 {
				return 0, errCorrupt
			}
		}
	}
	n, err := readVLIStream()
	if err != nil {
		return err
	}
	consumed := int64(1 + len(buf))
	for i := uint64(0); i < n; i++ {
		if _, err := readVLIStream(); err != nil {
			return err
		}
		consumed += int64(len(buf))
		if _, err := readVLIStream(); err != nil {
			return err
		}
		consumed += int64(len(buf))
	}
	pad := int((4 - consumed%4) % 4)
	if _, err := z.br.Discard(pad + 4); err != nil { // padding + CRC32
		return errCorrupt
	}
	// stream footer: 12 bytes
	if _, err := z.br.Discard(12); err != nil {
		return errCorrupt
	}
	z.inStream = false
	return nil
}
