// computeWidthColumns determines the column boundaries for the column width
// mode from the lines currently displayed: positions where all lines have
// a space start a new column.
func (root *Root) computeWidthColumns(m *Document) {
	var lines []contents
	for _, r := range root.scr.rows {
		if !r.valid {
			continue
		}
		lines = append(lines, m.getContents(r.number))
	}
	if len(lines) == 0 {
		m.columnWidths = nil
		return
	}
	maxLen := 0
	for _, lc := range lines {
		if len(lc) > maxLen {
			maxLen = len(lc)
		}
	}
	allSpace := make([]bool, maxLen)
	for i := range allSpace {
		allSpace[i] = true
	}
	for _, lc := range lines {
		for i, c := range lc {
			if c.width > 0 && c.mainc != ' ' {
				allSpace[i] = false
			}
		}
	}
	// boundaries: a non-space position following a space position
	var bounds []int
	for i := 1; i < maxLen; i++ {
		if allSpace[i-1] && !allSpace[i] {
			bounds = append(bounds, i)
		}
	}
	m.columnWidths = bounds
}

// widthColumnRanges returns the column ranges based on the computed widths.
func (m *Document) widthColumnRanges(lc contents) [][2]int {
	var res [][2]int
	prev := 0
	for _, b := range m.columnWidths {
		if b > len(lc) {
			b = len(lc)
		}
		res = append(res, [2]int{prev, b})
		prev = b
	}
	res = append(res, [2]int{prev, len(lc)})
	return res
}
